INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C1','kor',2,2,'u4',1,'문장 부호의 이름과 쓰임 — 마침표(.)·물음표(?)·느낌표(!)의 모양과 이름을 알고, 문장의 뜻에 맞게 문장 끝에 알맞은 부호 쓰기(미술관 관장 편지)',ARRAY['2국04-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C2','kor',2,2,'u4',3,'문장의 종류 알기 — 무엇을 설명하거나 생각을 나타내는 설명하는 문장, 무엇인가를 물어보는 묻는 문장, 기쁨·슬픔·놀람처럼 감정을 강하게 나타내는 감탄하는 문장을 부호와 뜻을 함께 보고 가르기',ARRAY['2국04-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C3','kor',2,2,'u4',3,'문장을 쓴 까닭 알기 — 대화나 글의 맥락에서 「공연이 시작하는 시간을 물으려고」처럼 문장의 뜻을 붙여 그 문장을 쓴 까닭 말하기',ARRAY['2국04-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C4','kor',2,2,'u4',5,'편지의 짜임 — 받는 사람·첫인사·전하고 싶은 말·끝인사·쓴 날짜·쓴 사람을 알고, 웃어른께는 「○○께」·「○○ 올림」으로 쓰기(편지는 안부·소식·마음을 전하는 글)',ARRAY['2국04-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C5','kor',2,2,'u4',5,'글쓴이의 마음 파악하기 — 민우의 편지처럼 문장의 종류와 쓴 까닭, 문장의 앞뒤 내용을 살펴 고마움·기쁨·속상함·미안함 같은 글쓴이의 마음 짐작하기',ARRAY['2국05-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C6','kor',2,2,'u4',7,'인물의 마음 짐작하기 — 이야기 상황과 인물의 말이나 행동을 근거로 화나다·황당하다·통쾌하다·어리둥절하다·부럽다·후회스럽다처럼 인물의 마음을 짐작하고 여러 낱말로 나타내기(「냄새 맡은 값」·「송아지와 바꾼 무」)',ARRAY['2국05-03']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C7','kor',2,2,'u4',7,'이야기의 흐름 파악하기 — 이야기에서 일이 일어난 차례를 정리하고 내용을 묻는 물음에 답하며 전체 흐름을 파악하기',ARRAY['2국05-03']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C8','kor',2,2,'u4',7,'인물의 마음을 생각하며 실감 나게 읽기 — 짐작한 마음에 어울리게 목소리 크기·빠르기·높낮이를 골라 읽고, 내용이 잘 전달되었는지·알맞은 크기였는지 점검하기(성우처럼 흉내가 목적이 아님)',ARRAY['2국01-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C9','kor',2,2,'u4',9,'인물에게 자신의 생각 전하기 — 인물의 마음과 비슷했던 자기 경험을 떠올려 칭찬·궁금한 점·바라는 점을 인물에게 말이나 편지로 전하고, 인물이 되어 질문에 답하기(핫시팅)',ARRAY['2국05-03']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C10','kor',2,2,'u4',11,'목소리 연극과 바른 자세로 발표하기 — 해설과 인물의 대사로 대본을 쓰고 역할을 나누어 연습해, 듣는 사람을 바라보며 알맞은 목소리로 실감 나게 발표하고 친구를 칭찬하기',ARRAY['2국01-04']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K2-2-u4-C11','kor',2,2,'u4',11,'뜻이 비슷한 낱말 — 뛰다/달리다, 굽히다/구부리다, 만나다/마주치다, 그치다/멈추다, 천둥/우레, 합치다/모으다처럼 뜻이 비슷해 바꾸어 쓸 수 있는 낱말 알기(기초 다지기)',ARRAY['2국04-03']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X01','kor',2,'u4',ARRAY['K2-2-u4-C1']::text[],'문장 부호의 이름과 모양을 헷갈린다(물음표를 느낌표라 부르기 등)','부호를 손가락으로 따라 그리며 이름을 소리 내어 말하기 — 점 하나 마침표, 갈고리 물음표, 막대 느낌표') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X02','kor',2,'u4',ARRAY['K2-2-u4-C1','K2-2-u4-C2']::text[],'문장의 뜻은 보지 않고 부호만으로 문장의 종류를 가르거나, 뜻에 맞지 않는 부호를 붙인다','「이 문장은 묻는 걸까, 알려 주는 걸까, 크게 느끼는 걸까?」 먼저 묻고 부호 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X03','kor',2,'u4',ARRAY['K2-2-u4-C2']::text[],'묻는 문장과 그 대답(설명하는 문장)을 헷갈린다','대답이 필요한 말인지 보기 — 대답을 기다리면 묻는 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X04','kor',2,'u4',ARRAY['K2-2-u4-C2']::text[],'감탄하는 문장을 칭찬하는 말로만 좁게 여겨 슬픔·놀람·아픔을 나타내는 문장은 감탄하는 문장이 아니라고 여긴다','「이가 너무 아파요!」·「너무 슬펐어!」도 감정을 강하게 나타내면 감탄하는 문장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X05','kor',2,'u4',ARRAY['K2-2-u4-C3','K2-2-u4-C5']::text[],'문장을 쓴 까닭을 문장의 뜻과 상관없이 말한다','「문장의 뜻 + ~하려고」 틀로 말하기 — 시간을 + 물으려고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X06','kor',2,'u4',ARRAY['K2-2-u4-C4']::text[],'편지의 부분(받는 사람·첫인사·끝인사·쓴 사람)을 헷갈리거나, 웃어른께 「○○에게 · ○○가」로 쓴다','편지 위에서 아래로 손가락을 내리며 부분 이름 말하기 — 웃어른께는 「께 · 올림」') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X07','kor',2,'u4',ARRAY['K2-2-u4-C5','K2-2-u4-C6']::text[],'한 문장만 떼어 보고 마음을 짐작해 앞뒤 내용과 맞지 않는 마음을 고른다','그 문장 바로 앞과 뒤를 함께 소리 내어 읽은 뒤 마음 고르기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X08','kor',2,'u4',ARRAY['K2-2-u4-C5','K2-2-u4-C6','K2-2-u4-C7','K2-2-u4-C9']::text[],'글이나 이야기에 없는 내용으로 답하거나 자기 생각을 사실처럼 고른다','「글 어디에 있지?」 하고 그 줄을 손가락으로 짚기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X09','kor',2,'u4',ARRAY['K2-2-u4-C6']::text[],'인물의 말이나 행동을 근거로 하지 않고 마음을 엉뚱하게(반대로) 짐작한다','말 · 행동에 밑줄 → 「나라면 이럴 때 어떤 마음?」 경험과 이어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X10','kor',2,'u4',ARRAY['K2-2-u4-C7']::text[],'이야기에서 일이 일어난 차례를 뒤섞는다','처음 · 그다음 · 마지막 세 칸에 그림 카드를 놓아 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X11','kor',2,'u4',ARRAY['K2-2-u4-C8','K2-2-u4-C10']::text[],'실감 나게 읽기를 무조건 크게·빠르게·성우처럼 흉내 내는 것으로 여긴다','「이 인물은 지금 어떤 마음?」을 먼저 말한 뒤 크기·빠르기·높낮이 중 하나만 바꿔 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X12','kor',2,'u4',ARRAY['K2-2-u4-C9']::text[],'인물에게 전하는 말에 놀림·비난을 넣거나 이야기와 상관없는 말을 한다','「칭찬 · 궁금한 점 · 바라는 점」 중 하나를 골라 인물의 마음을 헤아리며 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X13','kor',2,'u4',ARRAY['K2-2-u4-C10']::text[],'대본에서 해설과 인물의 대사를 구별하지 못한다','「해설:」은 상황, 「이름:」 뒤는 그 인물이 하는 말 — 색을 달리해 칠하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X14','kor',2,'u4',ARRAY['K2-2-u4-C11']::text[],'뜻이 비슷한 낱말과 뜻이 반대인 낱말을 헷갈린다(그치다 ↔ 놀다, 만나다 ↔ 헤어지다)','두 낱말을 같은 문장에 넣어 읽기 — 뜻이 그대로면 비슷한 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K2-2-u4-X15','kor',2,'u4',ARRAY['K2-2-u4-C10']::text[],'발표할 때 듣는 사람을 바라보지 않거나 알맞은 목소리 크기를 지키지 않는다','발표 전에 「바라보기 · 알맞은 크기 · 바른 자세」 세 손가락 점검') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
