INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L01_challenge#5','kor',2,2,'u4','L01','g2_2_kor_u4_L01_challenge','lesson_challenge','K2-2-u4-C1',3,'mc','auto','글을 읽을 때 문장 부호를 잘 살펴보면 좋은 점은?',ARRAY['K2-2-u4-X02','K2-2-u4-X08']::text[],false,'{"seq":5,"concept":"K2-2-u4-C1","difficulty":3,"kind":"mc","stem":"글을 읽을 때 문장 부호를 잘 살펴보면 좋은 점은?","options":[{"t":"문장의 뜻을 이해하는 데 도움이 돼요","correct":true},{"t":"글자 수를 빨리 셀 수 있어요","mis":"K2-2-u4-X02"},{"t":"읽지 않아도 돼요","mis":"K2-2-u4-X08"}],"explanation":["뜻을 이해해요.","105쪽 도움말이에요.","글쓴이의 생각도 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L01_challenge#6','kor',2,2,'u4','L01','g2_2_kor_u4_L01_challenge','lesson_challenge','K2-2-u4-C1',3,'mc','auto','「이 가방의 주인은 누구지( )」 빈칸에 알맞은 문장 부호는?',ARRAY['K2-2-u4-X02']::text[],false,'{"seq":6,"concept":"K2-2-u4-C1","difficulty":3,"kind":"mc","stem":"「이 가방의 주인은 누구지( )」 빈칸에 알맞은 문장 부호는?","options":[{"t":"?","correct":true},{"t":".","mis":"K2-2-u4-X02"},{"t":"!","mis":"K2-2-u4-X02"}],"explanation":["물음표예요.","지도서 172쪽이에요.","누구인지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L01_challenge#7','kor',2,2,'u4','L01','g2_2_kor_u4_L01_challenge','lesson_challenge','K2-2-u4-C1',3,'ox','auto','같은 문장도 글쓴이의 생각에 따라 쓰는 문장 부호가 달라질 수 있어요.',ARRAY['K2-2-u4-X02']::text[],false,'{"seq":7,"concept":"K2-2-u4-C1","difficulty":3,"kind":"ox","stem":"같은 문장도 글쓴이의 생각에 따라 쓰는 문장 부호가 달라질 수 있어요.","answer":"O","reason_options":[{"t":"묻는지, 설명하는지, 강하게 느끼는지에 따라 부호가 달라지니까","correct":true},{"t":"문장 부호는 아무거나 써도 되니까","mis":"K2-2-u4-X02"}],"mis":"K2-2-u4-X02","explanation":["생각에 따라 달라요.","105쪽 도움말이에요.","뜻에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L01_challenge#8','kor',2,2,'u4','L01','g2_2_kor_u4_L01_challenge','lesson_challenge','K2-2-u4-C1',4,'sa','auto','「.」의 이름을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u4-C1","difficulty":4,"kind":"sa","stem":"「.」의 이름을 쓰세요.","answer":["마침표"],"explanation":["마침표예요.","105쪽이에요.","설명하는 문장 끝에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L01_challenge#9','kor',2,2,'u4','L01','g2_2_kor_u4_L01_challenge','lesson_challenge','K2-2-u4-C1',4,'essay','teacher','마침표, 물음표, 느낌표가 들어간 문장을 하나씩 써서, 오늘 학교에서 있었던 일을 짧게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u4-C1","difficulty":4,"kind":"essay","stem":"마침표, 물음표, 느낌표가 들어간 문장을 하나씩 써서, 오늘 학교에서 있었던 일을 짧게 쓰세요.","answer_guide":{"answer":"예: 오늘 받아쓰기를 했다. 내일도 받아쓰기를 할까? 백 점을 받아서 정말 기뻤다!","scoring_points":["마침표 문장이 있어요","물음표 문장이 있어요","느낌표 문장이 있어요"]},"explanation":["부호를 하나씩 넣어요.","뜻에 맞게요.","지도서 172쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L01_challenge#10','kor',2,2,'u4','L01','g2_2_kor_u4_L01_challenge','lesson_challenge','K2-2-u4-C5',4,'essay','teacher','미술관 관장님께 답장을 쓴다면 어떤 말을 하고 싶은지 두 문장으로 쓰세요. 묻는 문장을 하나 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u4-C5","difficulty":4,"kind":"essay","stem":"미술관 관장님께 답장을 쓴다면 어떤 말을 하고 싶은지 두 문장으로 쓰세요. 묻는 문장을 하나 넣으세요.","answer_guide":{"answer":"예: 관장님, 초대해 주셔서 감사합니다. 11월 전시회에는 어떤 그림이 걸리나요?","scoring_points":["관장님 편지와 이어지는 내용이에요","묻는 문장이 있어요"]},"explanation":["편지 내용을 떠올려요.","물음표를 넣어요.","103쪽이에요."],"asset":{"type":"passage","lines":["초등학교 2학년 어린이들에게","여러분, 안녕하세요? 저는 미술관 관장입니다.","지난 화요일에 우리 미술관을 방문해 주어서 고마웠어요.","즐거운 시간 보냈나요? 저도 여러분을 만나 매우 반가웠어요!","어떤 작품이 가장 기억에 남았나요?","정말 멋진 작품들이에요!","여러분을 특별 전시회에 초대하고 싶어요. 꼭 와 주길 바라요.","미술관 관장 씀"],"title":"『국어』 102~103쪽 미술관 관장님의 편지(일부)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L03_basic#1','kor',2,2,'u4','L03','g2_2_kor_u4_L03_basic','lesson_basic','K2-2-u4-C2',1,'mc','auto','『국어』 107쪽 — 「우체국이 어디 있나요?」는 어떤 문장인가요?',ARRAY['K2-2-u4-X03','K2-2-u4-X04']::text[],false,'{"seq":1,"concept":"K2-2-u4-C2","difficulty":1,"kind":"mc","stem":"『국어』 107쪽 — 「우체국이 어디 있나요?」는 어떤 문장인가요?","options":[{"t":"묻는 문장","correct":true},{"t":"설명하는 문장","mis":"K2-2-u4-X03"},{"t":"감탄하는 문장","mis":"K2-2-u4-X04"}],"explanation":["묻는 문장이에요.","107쪽 예시 답안이에요.","물음표예요."],"asset":{"type":"passage","lines":["가 「난 줄넘기를 좋아해.」 「그래? 나는 축구가 가장 재미있어.」","나 「우체국이 어디 있나요?」","   「저기 모퉁이를 돌면 우체국이 바로 보이실 거예요.」","다 「이가 너무 아파요!」 「그래, 많이 아팠겠구나. 금방 치료해 줄게.」"],"title":"『국어』 106쪽 1번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
