INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L03_challenge#6','kor',2,2,'u4','L03','g2_2_kor_u4_L03_challenge','lesson_challenge','K2-2-u4-C2',3,'mc','auto','『국어활동』 48쪽 — 설명하는 문장은?',ARRAY['K2-2-u4-X03','K2-2-u4-X02']::text[],false,'{"seq":6,"concept":"K2-2-u4-C2","difficulty":3,"kind":"mc","stem":"『국어활동』 48쪽 — 설명하는 문장은?","options":[{"t":"화장실은 복도 끝에 있습니다.","correct":true},{"t":"실내화는 어디에 있나요?","mis":"K2-2-u4-X03"},{"t":"앗, 차가워!","mis":"K2-2-u4-X02"}],"explanation":["알려 주는 문장이에요.","국어활동 49쪽 예시 답안이에요.","마침표예요."],"asset":{"type":"passage","lines":["내일 우리 집에 올 수 있어? · 화장실은 복도 끝에 있습니다.","앗, 차가워! · 실내화는 어디에 있나요? · 줄넘기 줄 가져왔어?","시원하고 참 달콤하다! · 수영 수업은 두 시에 시작합니다.","오늘 점심에는 비빔밥을 먹을 거야."],"title":"『국어활동』 48~49쪽 1번 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L03_challenge#7','kor',2,2,'u4','L03','g2_2_kor_u4_L03_challenge','lesson_challenge','K2-2-u4-C2',3,'ox','auto','문장의 종류는 문장 부호만 보면 언제나 알 수 있으니 뜻은 보지 않아도 돼요.',ARRAY['K2-2-u4-X02']::text[],false,'{"seq":7,"concept":"K2-2-u4-C2","difficulty":3,"kind":"ox","stem":"문장의 종류는 문장 부호만 보면 언제나 알 수 있으니 뜻은 보지 않아도 돼요.","answer":"X","reason_options":[{"t":"부호와 함께 문장의 뜻도 살펴야 정확히 알 수 있으니까","correct":true},{"t":"부호가 가장 중요하니까","mis":"K2-2-u4-X02"}],"mis":"K2-2-u4-X02","explanation":["뜻도 함께 봐요.","지도서 169쪽이에요.","부호만이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L03_challenge#8','kor',2,2,'u4','L03','g2_2_kor_u4_L03_challenge','lesson_challenge','K2-2-u4-C2',4,'sa','auto','「무엇인가를 물어보는 문장」을 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u4-C2","difficulty":4,"kind":"sa","stem":"「무엇인가를 물어보는 문장」을 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["묻는 문장","묻는문장"],"explanation":["묻는 문장이에요.","107쪽이에요.","물음표를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L03_challenge#9','kor',2,2,'u4','L03','g2_2_kor_u4_L03_challenge','lesson_challenge','K2-2-u4-C2',4,'essay','teacher','『국어』 107쪽 3번처럼 설명하는 문장, 묻는 문장, 감탄하는 문장을 하나씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u4-C2","difficulty":4,"kind":"essay","stem":"『국어』 107쪽 3번처럼 설명하는 문장, 묻는 문장, 감탄하는 문장을 하나씩 쓰세요.","answer_guide":{"answer":"예: 설명하는 문장 — 우리 반은 스무 명입니다. / 묻는 문장 — 같이 줄넘기할래? / 감탄하는 문장 — 와, 눈이 정말 많이 왔다!","scoring_points":["설명하는 문장이 있어요","묻는 문장이 있어요","감탄하는 문장이 있어요"]},"explanation":["종류마다 하나씩요.","부호를 맞게 써요.","107쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L03_challenge#10','kor',2,2,'u4','L03','g2_2_kor_u4_L03_challenge','lesson_challenge','K2-2-u4-C3',4,'essay','teacher','「비가 온다.」를 묻는 문장과 감탄하는 문장으로 바꾸어 쓰고, 각각 언제 쓰면 좋을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u4-C3","difficulty":4,"kind":"essay","stem":"「비가 온다.」를 묻는 문장과 감탄하는 문장으로 바꾸어 쓰고, 각각 언제 쓰면 좋을지 쓰세요.","answer_guide":{"answer":"예: 비가 오니? — 밖에 비가 오는지 궁금할 때 / 비가 정말 많이 오는구나! — 비가 많이 와서 놀랐을 때","scoring_points":["묻는 문장으로 바꿨어요","감탄하는 문장으로 바꿨어요","쓸 때를 썼어요"]},"explanation":["종류를 바꿔요.","지도서 177쪽이에요.","쓰는 때도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L05_basic#1','kor',2,2,'u4','L05','g2_2_kor_u4_L05_basic','lesson_basic','K2-2-u4-C5',1,'mc','auto','『국어』 112쪽 (1) — 민우가 가방을 들기 힘들었던 까닭은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":1,"concept":"K2-2-u4-C5","difficulty":1,"kind":"mc","stem":"『국어』 112쪽 (1) — 민우가 가방을 들기 힘들었던 까닭은?","options":[{"t":"손을 다쳤기 때문이에요","correct":true},{"t":"가방이 새것이라서요","mis":"K2-2-u4-X08"},{"t":"달리기 연습을 해서요","mis":"K2-2-u4-X08"}],"explanation":["손을 다쳤어요.","112쪽 예시 답안이에요.","편지에 있어요."],"asset":{"type":"passage","lines":["지후에게","지후야, 안녕? 나 민우야.","지후야, 어제 네가 내 가방을 들어 주어서 큰 도움이 되었어.","내가 손을 다쳐서 가방을 어떻게 들까 걱정했거든.","그때 네가 도와준다고 해서 정말 기뻤어!","그런데 고맙다는 말을 제대로 하지 못해서 이렇게 편지를 써."],"title":"『국어』 110쪽 민우가 쓴 편지(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
