INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L05_challenge#5','kor',2,2,'u4','L05','g2_2_kor_u4_L05_challenge','lesson_challenge','K2-2-u4-C5',3,'mc','auto','「그래서 그동안 너한테 말도 제대로 하지 않았어.」에서 짐작할 수 있는 민우의 마음은?',ARRAY['K2-2-u4-X07','K2-2-u4-X09']::text[],false,'{"seq":5,"concept":"K2-2-u4-C5","difficulty":3,"kind":"mc","stem":"「그래서 그동안 너한테 말도 제대로 하지 않았어.」에서 짐작할 수 있는 민우의 마음은?","options":[{"t":"달리기에서 진 일이 말하기 싫을 만큼 속상했어요","correct":true},{"t":"지후를 아주 좋아했어요","mis":"K2-2-u4-X07"},{"t":"아무 마음도 없었어요","mis":"K2-2-u4-X09"}],"explanation":["앞에 「속상했어」가 있어요.","지도서 181쪽이에요.","앞뒤를 봐요."],"asset":{"type":"passage","lines":["지난 체육 시간에 달리기 경주를 했던 거 기억해? 네가 이겼잖아.","달리기만큼은 자신 있었는데 내가 지니까 많이 속상했어.","그래서 그동안 너한테 말도 제대로 하지 않았어.","그런데 너는 오히려 나를 걱정해 주고 가방도 들어 주어서 미안했어.","지후야, 나를 도와주어서 고마워!","앞으로도 친하게 지내자. 그럼 안녕. — 너의 친구 민우 보냄"],"title":"『국어』 110쪽 민우가 쓴 편지(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L05_challenge#6','kor',2,2,'u4','L05','g2_2_kor_u4_L05_challenge','lesson_challenge','K2-2-u4-C5',3,'mc','auto','민우가 「너는 운동도 잘하고, 마음도 참 따뜻한 멋진 친구야.」라고 쓴 마음은?',ARRAY['K2-2-u4-X09']::text[],false,'{"seq":6,"concept":"K2-2-u4-C5","difficulty":3,"kind":"mc","stem":"민우가 「너는 운동도 잘하고, 마음도 참 따뜻한 멋진 친구야.」라고 쓴 마음은?","options":[{"t":"지후를 좋게 여기고 앞으로도 친하게 지내고 싶은 마음","correct":true},{"t":"지후를 부러워해 화난 마음","mis":"K2-2-u4-X09"},{"t":"지후와 다투고 싶은 마음","mis":"K2-2-u4-X09"}],"explanation":["칭찬과 바람이에요.","110쪽이에요.","「친하게 지내자」로 이어져요."],"asset":{"type":"passage","lines":["지난 체육 시간에 달리기 경주를 했던 거 기억해? 네가 이겼잖아.","달리기만큼은 자신 있었는데 내가 지니까 많이 속상했어.","그래서 그동안 너한테 말도 제대로 하지 않았어.","그런데 너는 오히려 나를 걱정해 주고 가방도 들어 주어서 미안했어.","지후야, 나를 도와주어서 고마워!","앞으로도 친하게 지내자. 그럼 안녕. — 너의 친구 민우 보냄"],"title":"『국어』 110쪽 민우가 쓴 편지(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L05_challenge#7','kor',2,2,'u4','L05','g2_2_kor_u4_L05_challenge','lesson_challenge','K2-2-u4-C5',3,'ox','auto','글쓴이의 마음은 한 문장만 보고 정해야 해요.',ARRAY['K2-2-u4-X07']::text[],false,'{"seq":7,"concept":"K2-2-u4-C5","difficulty":3,"kind":"ox","stem":"글쓴이의 마음은 한 문장만 보고 정해야 해요.","answer":"X","reason_options":[{"t":"앞뒤 내용을 함께 살펴야 마음을 바르게 짐작할 수 있으니까","correct":true},{"t":"한 문장에 마음이 다 들어 있으니까","mis":"K2-2-u4-X07"}],"mis":"K2-2-u4-X07","explanation":["앞뒤를 함께 봐요.","지도서 169쪽이에요.","글 전체에서요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L05_challenge#8','kor',2,2,'u4','L05','g2_2_kor_u4_L05_challenge','lesson_challenge','K2-2-u4-C4',4,'sa','auto','편지에서 맨 처음에 쓰는 것은 무엇인가요? 「받는 ○○」의 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u4-C4","difficulty":4,"kind":"sa","stem":"편지에서 맨 처음에 쓰는 것은 무엇인가요? 「받는 ○○」의 빈칸 두 글자를 쓰세요.","answer":["사람"],"explanation":["받는 사람이에요.","111쪽이에요.","누구에게인지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L05_challenge#9','kor',2,2,'u4','L05','g2_2_kor_u4_L05_challenge','lesson_challenge','K2-2-u4-C5',4,'essay','teacher','민우의 편지를 다시 읽고, 민우의 마음이 바뀐 차례를 「처음에는 … 그다음에는 … 마지막에는 …」으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u4-C5","difficulty":4,"kind":"essay","stem":"민우의 편지를 다시 읽고, 민우의 마음이 바뀐 차례를 「처음에는 … 그다음에는 … 마지막에는 …」으로 쓰세요.","answer_guide":{"answer":"예: 처음에는 달리기에서 져서 속상했다. 그다음에는 지후가 도와주어 미안하고 고마웠다. 마지막에는 지후와 친하게 지내고 싶었다.","scoring_points":["속상함이 있어요","미안함·고마움이 있어요","친하게 지내고 싶은 마음이 있어요"]},"explanation":["편지 앞뒤를 봐요.","마음의 차례를 써요.","113쪽 (3)이에요."],"asset":{"type":"passage","lines":["지난 체육 시간에 달리기 경주를 했던 거 기억해? 네가 이겼잖아.","달리기만큼은 자신 있었는데 내가 지니까 많이 속상했어.","그래서 그동안 너한테 말도 제대로 하지 않았어.","그런데 너는 오히려 나를 걱정해 주고 가방도 들어 주어서 미안했어.","지후야, 나를 도와주어서 고마워!","앞으로도 친하게 지내자. 그럼 안녕. — 너의 친구 민우 보냄"],"title":"『국어』 110쪽 민우가 쓴 편지(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L05_challenge#10','kor',2,2,'u4','L05','g2_2_kor_u4_L05_challenge','lesson_challenge','K2-2-u4-C4',4,'essay','teacher','고마운 사람에게 편지를 쓰세요. 받는 사람·첫인사·전하고 싶은 말·끝인사·쓴 날짜·쓴 사람을 넣고, 감탄하는 문장을 하나 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u4-C4","difficulty":4,"kind":"essay","stem":"고마운 사람에게 편지를 쓰세요. 받는 사람·첫인사·전하고 싶은 말·끝인사·쓴 날짜·쓴 사람을 넣고, 감탄하는 문장을 하나 넣으세요.","answer_guide":{"answer":"예: 선생님께 / 선생님, 안녕하세요? 저 하윤이에요. 받아쓰기를 도와주셔서 감사합니다. 백 점을 받아서 정말 기뻤어요! 그럼 안녕히 계세요. / 20○○년 ○○월 ○○일 / 제자 하윤 올림","scoring_points":["편지의 여섯 부분이 있어요","감탄하는 문장이 있어요","웃어른께 맞게 썼어요"]},"explanation":["편지 짜임대로요.","마음을 담아요.","111쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L07_basic#1','kor',2,2,'u4','L07','g2_2_kor_u4_L07_basic','lesson_basic','K2-2-u4-C7',1,'mc','auto','『국어』 117쪽 (1) — 구두쇠 영감은 최 서방에게 무엇을 내놓으라고 했나요?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":1,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"『국어』 117쪽 (1) — 구두쇠 영감은 최 서방에게 무엇을 내놓으라고 했나요?","options":[{"t":"냄새 맡은 값","correct":true},{"t":"국밥 한 그릇","mis":"K2-2-u4-X08"},{"t":"엽전 주머니","mis":"K2-2-u4-X08"}],"explanation":["냄새 맡은 값이에요.","117쪽 예시 답안이에요.","억지를 부렸어요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L07_basic#2','kor',2,2,'u4','L07','g2_2_kor_u4_L07_basic','lesson_basic','K2-2-u4-C7',1,'mc','auto','「냄새 맡은 값」에 나오는 인물은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":2,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"「냄새 맡은 값」에 나오는 인물은?","options":[{"t":"구두쇠 영감과 최 서방","correct":true},{"t":"농부와 사또","mis":"K2-2-u4-X08"},{"t":"민우와 지후","mis":"K2-2-u4-X08"}],"explanation":["구두쇠 영감과 최 서방이에요.","114쪽이에요.","지도서 183쪽 질문이에요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
