INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L07_challenge#4','kor',2,2,'u4','L07','g2_2_kor_u4_L07_challenge','lesson_challenge','K2-2-u4-C6',3,'mc','auto','국밥집 사람들이 모두 웃음을 터뜨렸을 때 구두쇠 영감의 마음은?',ARRAY['K2-2-u4-X09']::text[],false,'{"seq":4,"concept":"K2-2-u4-C6","difficulty":3,"kind":"mc","stem":"국밥집 사람들이 모두 웃음을 터뜨렸을 때 구두쇠 영감의 마음은?","options":[{"t":"부끄럽고 창피해요","correct":true},{"t":"뿌듯해요","mis":"K2-2-u4-X09"},{"t":"고마워요","mis":"K2-2-u4-X09"}],"explanation":["부끄러워요.","118쪽 예시 답안이에요.","얼굴이 빨개졌어요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L07_challenge#5','kor',2,2,'u4','L07','g2_2_kor_u4_L07_challenge','lesson_challenge','K2-2-u4-C8',3,'mc','auto','『국어』 119쪽 (3) — 실감 나게 잘 읽었는지 확인할 것으로 알맞지 않은 것은?',ARRAY['K2-2-u4-X11']::text[],false,'{"seq":5,"concept":"K2-2-u4-C8","difficulty":3,"kind":"mc","stem":"『국어』 119쪽 (3) — 실감 나게 잘 읽었는지 확인할 것으로 알맞지 않은 것은?","options":[{"t":"성우처럼 목소리를 매번 바꾸었나요?","correct":true},{"t":"인물의 마음에 어울리는 목소리로 읽었나요?","mis":"K2-2-u4-X11"},{"t":"알맞은 크기로 읽었나요?","mis":"K2-2-u4-X11"}],"explanation":["흉내가 목적이 아니에요.","지도서 182쪽이에요.","내용이 잘 전달되게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L07_challenge#6','kor',2,2,'u4','L07','g2_2_kor_u4_L07_challenge','lesson_challenge','K2-2-u4-C6',3,'mc','auto','『국어활동』 「떡 먹기 내기」 — 호랑이가 떡을 같이 먹자고 하자 입을 삐죽이며 고개를 끄덕인 두꺼비와 토끼의 마음은?',ARRAY['K2-2-u4-X09']::text[],false,'{"seq":6,"concept":"K2-2-u4-C6","difficulty":3,"kind":"mc","stem":"『국어활동』 「떡 먹기 내기」 — 호랑이가 떡을 같이 먹자고 하자 입을 삐죽이며 고개를 끄덕인 두꺼비와 토끼의 마음은?","options":[{"t":"불만스럽고 억울해요","correct":true},{"t":"신나고 기뻐요","mis":"K2-2-u4-X09"},{"t":"고맙고 행복해요","mis":"K2-2-u4-X09"}],"explanation":["입을 삐죽였어요.","국어활동 56쪽 예시 답안이에요.","행동이 근거예요."],"asset":{"type":"scene","icon":"🐯🐸🐰🍡","text":"『국어활동』 「떡 먹기 내기」 — 호랑이가 떡을 같이 먹자고 하자 두꺼비와 토끼는 입을 삐죽이며 고개를 끄덕였어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L07_challenge#7','kor',2,2,'u4','L07','g2_2_kor_u4_L07_challenge','lesson_challenge','K2-2-u4-C8',3,'mc','auto','인물의 마음에 어울리는 목소리를 찾기 어려울 때 알맞은 방법은?',ARRAY['K2-2-u4-X11']::text[],false,'{"seq":7,"concept":"K2-2-u4-C8","difficulty":3,"kind":"mc","stem":"인물의 마음에 어울리는 목소리를 찾기 어려울 때 알맞은 방법은?","options":[{"t":"인물과 비슷한 마음을 느꼈던 내 경험을 떠올려요","correct":true},{"t":"무조건 크게 읽어요","mis":"K2-2-u4-X11"},{"t":"빨리 읽어요","mis":"K2-2-u4-X11"}],"explanation":["경험으로 공감해요.","지도서 185쪽이에요.","그다음 목소리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L07_challenge#8','kor',2,2,'u4','L07','g2_2_kor_u4_L07_challenge','lesson_challenge','K2-2-u4-C6',4,'sa','auto','인물의 마음을 짐작하려면 이야기 상황과 인물의 「말이나 (    )」을 살펴요. 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u4-C6","difficulty":4,"kind":"sa","stem":"인물의 마음을 짐작하려면 이야기 상황과 인물의 「말이나 (    )」을 살펴요. 빈칸 두 글자를 쓰세요.","answer":["행동"],"explanation":["행동이에요.","118쪽이에요.","말과 행동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L07_challenge#9','kor',2,2,'u4','L07','g2_2_kor_u4_L07_challenge','lesson_challenge','K2-2-u4-C6',4,'essay','teacher','「냄새 맡은 값」에서 한 장면을 골라, 이야기 상황 · 인물의 말이나 행동 · 인물의 마음을 차례대로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u4-C6","difficulty":4,"kind":"essay","stem":"「냄새 맡은 값」에서 한 장면을 골라, 이야기 상황 · 인물의 말이나 행동 · 인물의 마음을 차례대로 쓰세요.","answer_guide":{"answer":"예: 상황: 최 서방이 엽전 소리를 들려줌 / 말: 「이것은 엽전 소리가 아닌가?」 눈을 동그랗게 뜸 / 마음: 어리둥절하다","scoring_points":["이야기 상황이 있어요","말이나 행동이 있어요","알맞은 마음이에요"]},"explanation":["세 칸을 채워요.","118쪽 4번이에요.","근거를 써요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L07_challenge#10','kor',2,2,'u4','L07','g2_2_kor_u4_L07_challenge','lesson_challenge','K2-2-u4-C8',4,'essay','teacher','구두쇠 영감의 「아, 국밥 냄새를 맡았으면 값을 치르고 가야지.」를 어떤 목소리로 읽을지 쓰고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u4-C8","difficulty":4,"kind":"essay","stem":"구두쇠 영감의 「아, 국밥 냄새를 맡았으면 값을 치르고 가야지.」를 어떤 목소리로 읽을지 쓰고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 화가 난 듯 크고 높은 목소리로 읽겠어요. 눈을 부릅뜨고 말했으니 괘씸해하는 마음이기 때문이에요.","scoring_points":["목소리를 썼어요","까닭에 인물의 마음이 있어요"]},"explanation":["마음을 먼저 정해요.","목소리를 골라요.","119쪽이에요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L09_basic#1','kor',2,2,'u4','L09','g2_2_kor_u4_L09_basic','lesson_basic','K2-2-u4-C7',1,'mc','auto','『국어』 121쪽 (1) — 농부는 밭에서 뽑은 커다란 무를 어떻게 했나요?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":1,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"『국어』 121쪽 (1) — 농부는 밭에서 뽑은 커다란 무를 어떻게 했나요?","options":[{"t":"사또께 바쳤어요","correct":true},{"t":"시장에 팔았어요","mis":"K2-2-u4-X08"},{"t":"혼자 다 먹었어요","mis":"K2-2-u4-X08"}],"explanation":["사또께 바쳤어요.","121쪽 예시 답안이에요.","귀한 선물이에요."],"asset":{"type":"passage","lines":["농부가 밭에서 커다란 무를 간신히 뽑았습니다.","「세상에나! 이렇게 커다랗다니!」 농부는 신이 나서 어깨를 들썩거렸습니다.","「사또께 이 무를 바치고 싶습니다.」","사또는 껄껄껄 웃으며 보답으로 송아지 한 마리를 주었습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L09_basic#2','kor',2,2,'u4','L09','g2_2_kor_u4_L09_basic','lesson_basic','K2-2-u4-C7',1,'mc','auto','『국어』 121쪽 (2) — 욕심꾸러기 농부는 사또에게 무엇을 받았나요?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":2,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"『국어』 121쪽 (2) — 욕심꾸러기 농부는 사또에게 무엇을 받았나요?","options":[{"t":"커다란 무","correct":true},{"t":"송아지 두 마리","mis":"K2-2-u4-X08"},{"t":"엽전","mis":"K2-2-u4-X08"}],"explanation":["커다란 무예요.","121쪽 예시 답안이에요.","송아지를 바쳤어요."],"asset":{"type":"passage","lines":["욕심꾸러기 농부가 「아이고, 배 아파! 무 하나에 송아지 한 마리라니!」","「사또께 송아지를 갖다 바치면 더 큰 선물을 받겠지?」","사또는 며칠 전에 들어온 커다란 무를 욕심꾸러기 농부에게 주었습니다.","「아이고, 아까운 내 송아지!」 욕심꾸러기 농부는 울면서 돌아왔습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
