INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L09_challenge#4','kor',2,2,'u4','L09','g2_2_kor_u4_L09_challenge','lesson_challenge','K2-2-u4-C6',3,'mc','auto','커다란 무를 받은 사또가 「귀한 선물을 받았으니 나도 무엇인가 보답을 하고 싶네만.」이라고 한 마음은?',ARRAY['K2-2-u4-X09']::text[],false,'{"seq":4,"concept":"K2-2-u4-C6","difficulty":3,"kind":"mc","stem":"커다란 무를 받은 사또가 「귀한 선물을 받았으니 나도 무엇인가 보답을 하고 싶네만.」이라고 한 마음은?","options":[{"t":"흐뭇하고 고마워요","correct":true},{"t":"화나고 괘씸해요","mis":"K2-2-u4-X09"},{"t":"부끄러워요","mis":"K2-2-u4-X09"}],"explanation":["흐뭇해요.","121쪽 예시 답안이에요.","껄껄껄 웃었어요."],"asset":{"type":"passage","lines":["농부가 밭에서 커다란 무를 간신히 뽑았습니다.","「세상에나! 이렇게 커다랗다니!」 농부는 신이 나서 어깨를 들썩거렸습니다.","「사또께 이 무를 바치고 싶습니다.」","사또는 껄껄껄 웃으며 보답으로 송아지 한 마리를 주었습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L09_challenge#5','kor',2,2,'u4','L09','g2_2_kor_u4_L09_challenge','lesson_challenge','K2-2-u4-C7',3,'mc','auto','「송아지와 바꾼 무」의 흐름으로 알맞은 것은?',ARRAY['K2-2-u4-X10']::text[],false,'{"seq":5,"concept":"K2-2-u4-C7","difficulty":3,"kind":"mc","stem":"「송아지와 바꾼 무」의 흐름으로 알맞은 것은?","options":[{"t":"농부가 무를 바침 → 송아지를 받음 → 욕심꾸러기 농부가 송아지를 바침 → 무를 받음","correct":true},{"t":"욕심꾸러기 농부가 송아지를 바침 → 농부가 무를 바침 → 무를 받음 → 송아지를 받음","mis":"K2-2-u4-X10"},{"t":"농부가 송아지를 받음 → 무를 바침 → 무를 받음 → 송아지를 바침","mis":"K2-2-u4-X10"}],"explanation":["차례대로예요.","120쪽 그림이에요.","흐름부터 잡아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L09_challenge#6','kor',2,2,'u4','L09','g2_2_kor_u4_L09_challenge','lesson_challenge','K2-2-u4-C9',3,'mc','auto','인물에게 하고 싶은 말을 구체적으로 하려면 무엇을 떠올리면 좋을까요?',ARRAY['K2-2-u4-X12','K2-2-u4-X08']::text[],false,'{"seq":6,"concept":"K2-2-u4-C9","difficulty":3,"kind":"mc","stem":"인물에게 하고 싶은 말을 구체적으로 하려면 무엇을 떠올리면 좋을까요?","options":[{"t":"인물과 비슷한 마음을 느꼈던 내 경험","correct":true},{"t":"인물의 옷 색깔","mis":"K2-2-u4-X12"},{"t":"이야기의 쪽수","mis":"K2-2-u4-X08"}],"explanation":["비슷한 경험이에요.","지도서 186쪽이에요.","공감할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L09_challenge#7','kor',2,2,'u4','L09','g2_2_kor_u4_L09_challenge','lesson_challenge','K2-2-u4-C9',3,'ox','auto','인물에게 하고 싶은 말은 칭찬만 할 수 있어요.',ARRAY['K2-2-u4-X12']::text[],false,'{"seq":7,"concept":"K2-2-u4-C9","difficulty":3,"kind":"ox","stem":"인물에게 하고 싶은 말은 칭찬만 할 수 있어요.","answer":"X","reason_options":[{"t":"궁금한 점이나 바라는 점도 전할 수 있으니까","correct":true},{"t":"인물은 늘 잘했으니까","mis":"K2-2-u4-X12"}],"mis":"K2-2-u4-X12","explanation":["여러 가지를 전해요.","122쪽 (1)이에요.","칭찬·궁금함·바람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L09_challenge#8','kor',2,2,'u4','L09','g2_2_kor_u4_L09_challenge','lesson_challenge','K2-2-u4-C9',4,'sa','auto','『국어』 123쪽 — 이야기 속 인물이 되어 친구들의 말에 답하는 놀이를 할 때 인물이 된 친구는 어디에 앉나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u4-C9","difficulty":4,"kind":"sa","stem":"『국어』 123쪽 — 이야기 속 인물이 되어 친구들의 말에 답하는 놀이를 할 때 인물이 된 친구는 어디에 앉나요? 두 글자로 쓰세요.","answer":["의자"],"explanation":["의자예요.","123쪽이에요.","핫시팅이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L09_challenge#9','kor',2,2,'u4','L09','g2_2_kor_u4_L09_challenge','lesson_challenge','K2-2-u4-C9',4,'essay','teacher','「송아지와 바꾼 무」의 인물 한 명을 골라, 그 인물에게 전하고 싶은 말을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u4-C9","difficulty":4,"kind":"essay","stem":"「송아지와 바꾼 무」의 인물 한 명을 골라, 그 인물에게 전하고 싶은 말을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 농부 아저씨, 귀한 무를 사또께 선물한 모습이 대단해요. 저라면 혼자 먹고 싶었을 것 같거든요.","scoring_points":["인물을 골랐어요","전하고 싶은 말이 있어요","까닭이 있어요"]},"explanation":["인물을 정해요.","까닭을 함께요.","122쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L09_challenge#10','kor',2,2,'u4','L09','g2_2_kor_u4_L09_challenge','lesson_challenge','K2-2-u4-C9',4,'essay','teacher','욕심꾸러기 농부에게 인터뷰할 질문을 하나 쓰고, 욕심꾸러기 농부가 되어 대답을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u4-C9","difficulty":4,"kind":"essay","stem":"욕심꾸러기 농부에게 인터뷰할 질문을 하나 쓰고, 욕심꾸러기 농부가 되어 대답을 쓰세요.","answer_guide":{"answer":"예: 질문: 송아지를 바칠 때 어떤 선물을 기대하셨나요? / 대답: 송아지보다 더 큰 선물을 받을 줄 알았어요. 이제는 욕심을 부린 게 부끄러워요.","scoring_points":["질문이 있어요","인물의 마음에 맞는 대답이에요"]},"explanation":["인물의 마음을 짐작해요.","지도서 201쪽 평가와 같아요.","123쪽이에요."],"asset":{"type":"passage","lines":["욕심꾸러기 농부가 「아이고, 배 아파! 무 하나에 송아지 한 마리라니!」","「사또께 송아지를 갖다 바치면 더 큰 선물을 받겠지?」","사또는 며칠 전에 들어온 커다란 무를 욕심꾸러기 농부에게 주었습니다.","「아이고, 아까운 내 송아지!」 욕심꾸러기 농부는 울면서 돌아왔습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L11_basic#1','kor',2,2,'u4','L11','g2_2_kor_u4_L11_basic','lesson_basic','K2-2-u4-C10',1,'mc','auto','『국어』 124쪽 대본에서 소금 장수와 기름 장수가 만난 곳은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":1,"concept":"K2-2-u4-C10","difficulty":1,"kind":"mc","stem":"『국어』 124쪽 대본에서 소금 장수와 기름 장수가 만난 곳은?","options":[{"t":"호랑이 뱃속","correct":true},{"t":"기름 장수 집","mis":"K2-2-u4-X08"},{"t":"장터","mis":"K2-2-u4-X08"}],"explanation":["호랑이 뱃속이에요.","124쪽이에요.","해설에 있어요."],"asset":{"type":"passage","lines":["해설: 호랑이 뱃속에서 소금 장수와 기름 장수가 만났습니다.","기름 장수: 아이고, 깜깜해. 거기 누구 있소?","소금 장수: 누구요? 누가 부르는 거요?","기름 장수: 나는 기름 장수인데 당신은 누구요?","소금 장수: 나는 소금 장수요. 당신도 호랑이한테 잡아먹혔소?","해설: 둘은 서로 반가웠지만 깜깜해서 서로가 보이지 않았습니다."],"title":"『국어』 124쪽 목소리 연극 대본 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
