INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L11_challenge#6','kor',2,2,'u4','L11','g2_2_kor_u4_L11_challenge','lesson_challenge','K2-2-u4-C10',3,'mc','auto','목소리 연극을 보는 친구(관찰자)가 할 일로 알맞은 것은?',ARRAY['K2-2-u4-X15']::text[],false,'{"seq":6,"concept":"K2-2-u4-C10","difficulty":3,"kind":"mc","stem":"목소리 연극을 보는 친구(관찰자)가 할 일로 알맞은 것은?","options":[{"t":"알맞은 태도로 경청하며 인물의 마음을 잘 표현했는지 살펴요","correct":true},{"t":"딴짓을 해요","mis":"K2-2-u4-X15"},{"t":"대사를 따라 소리쳐요","mis":"K2-2-u4-X15"}],"explanation":["경청해요.","지도서 193쪽이에요.","동료 평가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L11_challenge#7','kor',2,2,'u4','L11','g2_2_kor_u4_L11_challenge','lesson_challenge','K2-2-u4-C10',3,'ox','auto','발표할 때에는 듣는 사람을 바라보며 알맞은 목소리 크기로 말해요.',ARRAY['K2-2-u4-X15']::text[],false,'{"seq":7,"concept":"K2-2-u4-C10","difficulty":3,"kind":"ox","stem":"발표할 때에는 듣는 사람을 바라보며 알맞은 목소리 크기로 말해요.","answer":"O","reason_options":[{"t":"그래야 내 생각이 잘 전해지니까","correct":true},{"t":"바닥을 보고 말해야 덜 떨리니까","mis":"K2-2-u4-X15"}],"mis":"K2-2-u4-X15","explanation":["바라보며 말해요.","지도서 199쪽이에요.","바른 자세예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L11_challenge#8','kor',2,2,'u4','L11','g2_2_kor_u4_L11_challenge','lesson_challenge','K2-2-u4-C11',4,'sa','auto','「굽히다」와 뜻이 비슷한 네 글자 낱말을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K2-2-u4-C11","difficulty":4,"kind":"sa","stem":"「굽히다」와 뜻이 비슷한 네 글자 낱말을 쓰세요.","answer":["구부리다"],"explanation":["구부리다예요.","128쪽이에요.","바꾸어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L11_challenge#9','kor',2,2,'u4','L11','g2_2_kor_u4_L11_challenge','lesson_challenge','K2-2-u4-C10',4,'essay','teacher','『국어』 124쪽 대본에 이어질 장면을 해설 한 줄과 두 인물의 대사로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K2-2-u4-C10","difficulty":4,"kind":"essay","stem":"『국어』 124쪽 대본에 이어질 장면을 해설 한 줄과 두 인물의 대사로 쓰세요.","answer_guide":{"answer":"예: 해설: 둘은 손을 더듬어 서로를 찾았습니다. / 기름 장수: 여기서 어떻게 나가지요? / 소금 장수: 걱정 마시오. 내게 좋은 생각이 있소.","scoring_points":["해설이 있어요","두 인물의 대사가 있어요","인물의 마음에 맞아요"]},"explanation":["해설과 대사를 나눠요.","124쪽이에요.","마음을 생각해요."],"asset":{"type":"passage","lines":["해설: 호랑이 뱃속에서 소금 장수와 기름 장수가 만났습니다.","기름 장수: 아이고, 깜깜해. 거기 누구 있소?","소금 장수: 누구요? 누가 부르는 거요?","기름 장수: 나는 기름 장수인데 당신은 누구요?","소금 장수: 나는 소금 장수요. 당신도 호랑이한테 잡아먹혔소?","해설: 둘은 서로 반가웠지만 깜깜해서 서로가 보이지 않았습니다."],"title":"『국어』 124쪽 목소리 연극 대본 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_L11_challenge#10','kor',2,2,'u4','L11','g2_2_kor_u4_L11_challenge','lesson_challenge','K2-2-u4-C9',4,'essay','teacher','알고 있는 옛이야기의 인물 한 명에게 편지를 쓰세요. 인물에게 하고 싶은 말과 그 까닭을 넣으세요.','{}'::text[],false,'{"seq":10,"concept":"K2-2-u4-C9","difficulty":4,"kind":"essay","stem":"알고 있는 옛이야기의 인물 한 명에게 편지를 쓰세요. 인물에게 하고 싶은 말과 그 까닭을 넣으세요.","answer_guide":{"answer":"예: 흥부에게 / 흥부야, 안녕? 나는 ○○이야. 제비 다리를 고쳐 준 네 착한 마음이 멋졌어. 나도 다친 동물을 보면 도와주고 싶어. 그럼 안녕. / ○○가","scoring_points":["편지 짜임이 있어요","하고 싶은 말이 있어요","까닭이 있어요"]},"explanation":["인물을 정해요.","편지로 전해요.","지도서 195쪽 예시 2예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
