INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#4','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C5',1,'mc','auto','민우가 지후에게 고마운 까닭은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":4,"concept":"K2-2-u4-C5","difficulty":1,"kind":"mc","stem":"민우가 지후에게 고마운 까닭은?","options":[{"t":"지후가 가방을 들어 주어서","correct":true},{"t":"지후가 선물을 주어서","mis":"K2-2-u4-X08"},{"t":"지후가 달리기를 져 주어서","mis":"K2-2-u4-X08"}],"explanation":["가방을 들어 주었어요.","110쪽이에요.","편지에 있어요."],"asset":{"type":"passage","lines":["지후에게","지후야, 안녕? 나 민우야.","지후야, 어제 네가 내 가방을 들어 주어서 큰 도움이 되었어.","내가 손을 다쳐서 가방을 어떻게 들까 걱정했거든.","그때 네가 도와준다고 해서 정말 기뻤어!","그런데 고맙다는 말을 제대로 하지 못해서 이렇게 편지를 써."],"title":"『국어』 110쪽 민우가 쓴 편지(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#5','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C7',1,'mc','auto','「냄새 맡은 값」에서 최 서방이 생각한 해결 방법은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":5,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"「냄새 맡은 값」에서 최 서방이 생각한 해결 방법은?","options":[{"t":"엽전 소리를 들려주었어요","correct":true},{"t":"국밥을 사 먹었어요","mis":"K2-2-u4-X08"},{"t":"도망쳤어요","mis":"K2-2-u4-X08"}],"explanation":["엽전 소리예요.","127쪽 예시 답안이에요.","재치 있는 방법이에요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#6','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C7',1,'mc','auto','「송아지와 바꾼 무」에서 농부가 받은 것은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":6,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"「송아지와 바꾼 무」에서 농부가 받은 것은?","options":[{"t":"송아지","correct":true},{"t":"커다란 무","mis":"K2-2-u4-X08"},{"t":"엽전","mis":"K2-2-u4-X08"}],"explanation":["송아지예요.","지도서 191쪽이에요.","보답이에요."],"asset":{"type":"passage","lines":["농부가 밭에서 커다란 무를 간신히 뽑았습니다.","「세상에나! 이렇게 커다랗다니!」 농부는 신이 나서 어깨를 들썩거렸습니다.","「사또께 이 무를 바치고 싶습니다.」","사또는 껄껄껄 웃으며 보답으로 송아지 한 마리를 주었습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
