INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#8','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C10',1,'mc','auto','목소리 연극 대본에서 상황을 알려 주는 부분은?',ARRAY['K2-2-u4-X13']::text[],false,'{"seq":8,"concept":"K2-2-u4-C10","difficulty":1,"kind":"mc","stem":"목소리 연극 대본에서 상황을 알려 주는 부분은?","options":[{"t":"해설","correct":true},{"t":"대사","mis":"K2-2-u4-X13"},{"t":"제목","mis":"K2-2-u4-X13"}],"explanation":["해설이에요.","124쪽이에요.","상황을 알려요."],"asset":{"type":"passage","lines":["해설: 호랑이 뱃속에서 소금 장수와 기름 장수가 만났습니다.","기름 장수: 아이고, 깜깜해. 거기 누구 있소?","소금 장수: 누구요? 누가 부르는 거요?","기름 장수: 나는 기름 장수인데 당신은 누구요?","소금 장수: 나는 소금 장수요. 당신도 호랑이한테 잡아먹혔소?","해설: 둘은 서로 반가웠지만 깜깜해서 서로가 보이지 않았습니다."],"title":"『국어』 124쪽 목소리 연극 대본 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#9','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C3',2,'mc','auto','「공연은 몇 시에 시작하나요?」를 쓴 까닭은?',ARRAY['K2-2-u4-X05']::text[],false,'{"seq":9,"concept":"K2-2-u4-C3","difficulty":2,"kind":"mc","stem":"「공연은 몇 시에 시작하나요?」를 쓴 까닭은?","options":[{"t":"공연이 시작하는 시간을 물으려고","correct":true},{"t":"공연이 재미있다는 느낌을 나타내려고","mis":"K2-2-u4-X05"},{"t":"공연장을 설명하려고","mis":"K2-2-u4-X05"}],"explanation":["시간을 물으려고요.","109쪽이에요.","뜻 + ~하려고요."],"asset":{"type":"passage","lines":["가 공연은 몇 시에 시작하나요?  나 2시 30분에 시작합니다.","다 여기 상추 씨앗이 있어.  라 씨앗이 참 작구나!","마 주인공이 병에 걸려서 너무 슬펐어!","바 그 뒤에 주인공은 어떻게 되었을까?","사 종이 가장자리를 모두 안으로 접으면 강아지 모양이 된단다.","아 우아, 신기해요!  자 나랑 공놀이할래?"],"title":"『국어』 108쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#10','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C6',2,'mc','auto','눈을 부릅뜨고 「값을 치르고 가야지.」 하는 구두쇠 영감의 마음은?',ARRAY['K2-2-u4-X09']::text[],false,'{"seq":10,"concept":"K2-2-u4-C6","difficulty":2,"kind":"mc","stem":"눈을 부릅뜨고 「값을 치르고 가야지.」 하는 구두쇠 영감의 마음은?","options":[{"t":"화나고 괘씸해요","correct":true},{"t":"고맙고 기뻐요","mis":"K2-2-u4-X09"},{"t":"부끄러워요","mis":"K2-2-u4-X09"}],"explanation":["괘씸해요.","118쪽 예시 답안이에요.","부릅뜬 눈이 근거예요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#11','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C2',2,'match','auto','문장과 문장의 종류를 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-2-u4-C2","difficulty":2,"kind":"match","stem":"문장과 문장의 종류를 이어 보세요.","pairs":[{"l":"실내화는 어디에 있나요?","r":"묻는 문장"},{"l":"수영 수업은 두 시에 시작합니다.","r":"설명하는 문장"},{"l":"시원하고 참 달콤하다!","r":"감탄하는 문장"}],"mis":"K2-2-u4-X03","explanation":["물음 · 설명 · 감탄이에요.","국어활동 49쪽이에요.","부호와 뜻이에요."],"asset":{"type":"passage","lines":["내일 우리 집에 올 수 있어? · 화장실은 복도 끝에 있습니다.","앗, 차가워! · 실내화는 어디에 있나요? · 줄넘기 줄 가져왔어?","시원하고 참 달콤하다! · 수영 수업은 두 시에 시작합니다.","오늘 점심에는 비빔밥을 먹을 거야."],"title":"『국어활동』 48~49쪽 1번 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#12','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C2',2,'ox','auto','「이가 너무 아파요!」처럼 아픔이나 슬픔을 강하게 나타내는 문장도 감탄하는 문장이에요.',ARRAY['K2-2-u4-X04']::text[],false,'{"seq":12,"concept":"K2-2-u4-C2","difficulty":2,"kind":"ox","stem":"「이가 너무 아파요!」처럼 아픔이나 슬픔을 강하게 나타내는 문장도 감탄하는 문장이에요.","answer":"O","reason_options":[{"t":"감탄하는 문장은 감정을 강하게 나타내는 문장이니까","correct":true},{"t":"감탄하는 문장은 칭찬할 때만 쓰니까","mis":"K2-2-u4-X04"}],"mis":"K2-2-u4-X04","explanation":["아픔도 감정이에요.","지도서 176쪽이에요.","느낌표를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#13','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C5',2,'mc','auto','「그때 네가 도와준다고 해서 정말 기뻤어!」에 담긴 마음은?',ARRAY['K2-2-u4-X09','K2-2-u4-X07']::text[],false,'{"seq":13,"concept":"K2-2-u4-C5","difficulty":2,"kind":"mc","stem":"「그때 네가 도와준다고 해서 정말 기뻤어!」에 담긴 마음은?","options":[{"t":"기쁘고 고마운 마음","correct":true},{"t":"화난 마음","mis":"K2-2-u4-X09"},{"t":"미안한 마음만","mis":"K2-2-u4-X07"}],"explanation":["기쁘고 고마워요.","113쪽이에요.","느낌표가 근거예요."],"asset":{"type":"passage","lines":["지후에게","지후야, 안녕? 나 민우야.","지후야, 어제 네가 내 가방을 들어 주어서 큰 도움이 되었어.","내가 손을 다쳐서 가방을 어떻게 들까 걱정했거든.","그때 네가 도와준다고 해서 정말 기뻤어!","그런데 고맙다는 말을 제대로 하지 못해서 이렇게 편지를 써."],"title":"『국어』 110쪽 민우가 쓴 편지(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
