INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#16','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C8',2,'mc','auto','「아니, 뭐라고?」 하며 얼굴이 빨개진 구두쇠 영감을 읽는 목소리로 알맞은 것은?',ARRAY['K2-2-u4-X11']::text[],false,'{"seq":16,"concept":"K2-2-u4-C8","difficulty":2,"kind":"mc","stem":"「아니, 뭐라고?」 하며 얼굴이 빨개진 구두쇠 영감을 읽는 목소리로 알맞은 것은?","options":[{"t":"당황하고 창피해 화를 내듯이","correct":true},{"t":"느릿느릿 졸린 목소리로","mis":"K2-2-u4-X11"},{"t":"신나서 노래하듯이","mis":"K2-2-u4-X11"}],"explanation":["창피한 마음이에요.","119쪽이에요.","마음 먼저요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
