INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#18','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C3',3,'mc','auto','「어제 네가 내 가방을 들어 주어서 큰 도움이 되었어.」를 쓴 까닭은?',ARRAY['K2-2-u4-X05']::text[],false,'{"seq":18,"concept":"K2-2-u4-C3","difficulty":3,"kind":"mc","stem":"「어제 네가 내 가방을 들어 주어서 큰 도움이 되었어.」를 쓴 까닭은?","options":[{"t":"고마운 까닭을 설명하려고","correct":true},{"t":"가방이 어디 있는지 물으려고","mis":"K2-2-u4-X05"},{"t":"기쁜 느낌을 강하게 나타내려고","mis":"K2-2-u4-X05"}],"explanation":["고마운 까닭이에요.","112쪽이에요.","설명하는 문장이에요."],"asset":{"type":"passage","lines":["지후에게","지후야, 안녕? 나 민우야.","지후야, 어제 네가 내 가방을 들어 주어서 큰 도움이 되었어.","내가 손을 다쳐서 가방을 어떻게 들까 걱정했거든.","그때 네가 도와준다고 해서 정말 기뻤어!","그런데 고맙다는 말을 제대로 하지 못해서 이렇게 편지를 써."],"title":"『국어』 110쪽 민우가 쓴 편지(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#19','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C7',3,'mc','auto','「냄새 맡은 값」의 일이 일어난 차례로 알맞은 것은?',ARRAY['K2-2-u4-X10']::text[],false,'{"seq":19,"concept":"K2-2-u4-C7","difficulty":3,"kind":"mc","stem":"「냄새 맡은 값」의 일이 일어난 차례로 알맞은 것은?","options":[{"t":"냄새를 맡았다 → 값을 달라고 했다 → 엽전 소리로 값을 냈다 → 영감이 얼굴이 빨개졌다","correct":true},{"t":"값을 달라고 했다 → 냄새를 맡았다 → 영감이 얼굴이 빨개졌다 → 엽전 소리로 값을 냈다","mis":"K2-2-u4-X10"},{"t":"엽전 소리로 값을 냈다 → 냄새를 맡았다 → 값을 달라고 했다 → 영감이 얼굴이 빨개졌다","mis":"K2-2-u4-X10"}],"explanation":["차례대로예요.","118쪽이에요.","흐름부터요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#20','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C2',3,'mc','auto','지도서 199쪽 평가 — 생일 초대장에 쓸 묻는 문장으로 알맞은 것은?',ARRAY['K2-2-u4-X03','K2-2-u4-X02']::text[],false,'{"seq":20,"concept":"K2-2-u4-C2","difficulty":3,"kind":"mc","stem":"지도서 199쪽 평가 — 생일 초대장에 쓸 묻는 문장으로 알맞은 것은?","options":[{"t":"토요일에 우리 집에 와 줄 수 있니?","correct":true},{"t":"토요일은 내 생일이야.","mis":"K2-2-u4-X03"},{"t":"정말 신난다!","mis":"K2-2-u4-X02"}],"explanation":["묻는 문장이에요.","지도서 199쪽이에요.","물음표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#21','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C9',3,'mc','auto','인물에게 하고 싶은 말을 구체적으로 하려면 무엇을 떠올리면 좋을까요?',ARRAY['K2-2-u4-X12','K2-2-u4-X08']::text[],false,'{"seq":21,"concept":"K2-2-u4-C9","difficulty":3,"kind":"mc","stem":"인물에게 하고 싶은 말을 구체적으로 하려면 무엇을 떠올리면 좋을까요?","options":[{"t":"인물과 비슷한 마음을 느꼈던 내 경험","correct":true},{"t":"인물의 옷 색깔","mis":"K2-2-u4-X12"},{"t":"이야기의 쪽수","mis":"K2-2-u4-X08"}],"explanation":["비슷한 경험이에요.","지도서 186쪽이에요.","공감해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#22','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C10',3,'mc','auto','목소리 연극 대본에서 「소금 장수: 누구요? 누가 부르는 거요?」의 「누구요? 누가 부르는 거요?」는 무엇인가요?',ARRAY['K2-2-u4-X13']::text[],false,'{"seq":22,"concept":"K2-2-u4-C10","difficulty":3,"kind":"mc","stem":"목소리 연극 대본에서 「소금 장수: 누구요? 누가 부르는 거요?」의 「누구요? 누가 부르는 거요?」는 무엇인가요?","options":[{"t":"소금 장수의 대사","correct":true},{"t":"해설","mis":"K2-2-u4-X13"},{"t":"제목","mis":"K2-2-u4-X13"}],"explanation":["인물의 대사예요.","124쪽이에요.","이름 뒤가 대사예요."],"asset":{"type":"passage","lines":["해설: 호랑이 뱃속에서 소금 장수와 기름 장수가 만났습니다.","기름 장수: 아이고, 깜깜해. 거기 누구 있소?","소금 장수: 누구요? 누가 부르는 거요?","기름 장수: 나는 기름 장수인데 당신은 누구요?","소금 장수: 나는 소금 장수요. 당신도 호랑이한테 잡아먹혔소?","해설: 둘은 서로 반가웠지만 깜깜해서 서로가 보이지 않았습니다."],"title":"『국어』 124쪽 목소리 연극 대본 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#23','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C2',4,'sa','auto','기쁨, 슬픔, 놀람처럼 감정을 강하게 나타내는 문장을 무엇이라고 하나요? 「○○하는 문장」의 빈칸 두 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u4-C2","difficulty":4,"kind":"sa","stem":"기쁨, 슬픔, 놀람처럼 감정을 강하게 나타내는 문장을 무엇이라고 하나요? 「○○하는 문장」의 빈칸 두 글자를 쓰세요.","answer":["감탄"],"explanation":["감탄이에요.","지도서 176쪽이에요.","느낌표를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#24','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C2',4,'essay','teacher','지도서 199쪽 평가 — 설명하는 문장, 묻는 문장, 감탄하는 문장이 모두 나타나도록 생일 초대장을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u4-C2","difficulty":4,"kind":"essay","stem":"지도서 199쪽 평가 — 설명하는 문장, 묻는 문장, 감탄하는 문장이 모두 나타나도록 생일 초대장을 쓰세요.","answer_guide":{"answer":"예: 하윤아, 이번 토요일은 내 생일이야. 두 시에 우리 집에서 생일잔치를 해. 와 줄 수 있니? 네가 오면 정말 즐거울 거야!","scoring_points":["설명하는 문장이 있어요","묻는 문장이 있어요","감탄하는 문장이 있어요","문장 부호를 알맞게 썼어요"]},"explanation":["세 종류를 다 넣어요.","부호를 살펴요.","지도서 199쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_a#25','kor',2,2,'u4','','g2_2_kor_u4_review_a','unit_review','K2-2-u4-C6',4,'essay','teacher','지도서 201쪽 평가 — 재미있게 읽은 이야기의 인물 한 명을 골라 인터뷰 질문 두 개와 인물이 되어 쓴 답을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u4-C6","difficulty":4,"kind":"essay","stem":"지도서 201쪽 평가 — 재미있게 읽은 이야기의 인물 한 명을 골라 인터뷰 질문 두 개와 인물이 되어 쓴 답을 쓰세요.","answer_guide":{"answer":"예: 이야기: 냄새 맡은 값 / 인물: 최 서방 / 질문: 값을 내라고 했을 때 어떤 마음이 들었나요? — 답: 너무 어이없었어요. / 질문: 엽전 소리를 들려줄 때 어떤 표정이었나요? — 답: 웃음이 가득했어요.","scoring_points":["이야기와 인물이 있어요","질문이 두 개예요","인물의 마음에 맞는 답이에요"]},"explanation":["마음을 묻는 질문이에요.","지도서 201쪽이에요.","인물이 되어 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
