INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#3','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C4',1,'mc','auto','편지에서 「너의 친구 민우 보냄」은 어느 부분인가요?',ARRAY['K2-2-u4-X06']::text[],false,'{"seq":3,"concept":"K2-2-u4-C4","difficulty":1,"kind":"mc","stem":"편지에서 「너의 친구 민우 보냄」은 어느 부분인가요?","options":[{"t":"쓴 사람","correct":true},{"t":"받는 사람","mis":"K2-2-u4-X06"},{"t":"첫인사","mis":"K2-2-u4-X06"}],"explanation":["쓴 사람이에요.","111쪽이에요.","맨 아래에 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#4','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C5',1,'mc','auto','달리기 경주에서 이긴 사람은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":4,"concept":"K2-2-u4-C5","difficulty":1,"kind":"mc","stem":"달리기 경주에서 이긴 사람은?","options":[{"t":"지후","correct":true},{"t":"민우","mis":"K2-2-u4-X08"},{"t":"관장님","mis":"K2-2-u4-X08"}],"explanation":["지후예요.","110쪽이에요.","「네가 이겼잖아」예요."],"asset":{"type":"passage","lines":["지난 체육 시간에 달리기 경주를 했던 거 기억해? 네가 이겼잖아.","달리기만큼은 자신 있었는데 내가 지니까 많이 속상했어.","그래서 그동안 너한테 말도 제대로 하지 않았어.","그런데 너는 오히려 나를 걱정해 주고 가방도 들어 주어서 미안했어.","지후야, 나를 도와주어서 고마워!","앞으로도 친하게 지내자. 그럼 안녕. — 너의 친구 민우 보냄"],"title":"『국어』 110쪽 민우가 쓴 편지(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#5','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C7',1,'mc','auto','구두쇠 영감은 무엇을 하는 사람이었나요?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":5,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"구두쇠 영감은 무엇을 하는 사람이었나요?","options":[{"t":"국밥집을 차렸어요","correct":true},{"t":"떡집을 차렸어요","mis":"K2-2-u4-X08"},{"t":"농사를 지었어요","mis":"K2-2-u4-X08"}],"explanation":["국밥집이에요.","114쪽이에요.","장사가 잘됐어요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#6','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C7',1,'mc','auto','욕심꾸러기 농부가 사또에게 바친 것은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":6,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"욕심꾸러기 농부가 사또에게 바친 것은?","options":[{"t":"송아지","correct":true},{"t":"커다란 무","mis":"K2-2-u4-X08"},{"t":"떡","mis":"K2-2-u4-X08"}],"explanation":["송아지예요.","지도서 191쪽이에요.","더 큰 선물을 바랐어요."],"asset":{"type":"passage","lines":["욕심꾸러기 농부가 「아이고, 배 아파! 무 하나에 송아지 한 마리라니!」","「사또께 송아지를 갖다 바치면 더 큰 선물을 받겠지?」","사또는 며칠 전에 들어온 커다란 무를 욕심꾸러기 농부에게 주었습니다.","「아이고, 아까운 내 송아지!」 욕심꾸러기 농부는 울면서 돌아왔습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
