INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#9','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C3',2,'mc','auto','「종이 가장자리를 모두 안으로 접으면 강아지 모양이 된단다.」를 쓴 까닭은?',ARRAY['K2-2-u4-X05','K2-2-u4-X03']::text[],false,'{"seq":9,"concept":"K2-2-u4-C3","difficulty":2,"kind":"mc","stem":"「종이 가장자리를 모두 안으로 접으면 강아지 모양이 된단다.」를 쓴 까닭은?","options":[{"t":"종이 접는 방법을 설명하려고","correct":true},{"t":"강아지가 귀엽다는 느낌을 나타내려고","mis":"K2-2-u4-X05"},{"t":"강아지가 어디 있는지 물으려고","mis":"K2-2-u4-X03"}],"explanation":["접는 방법이에요.","109쪽이에요.","설명하는 문장이에요."],"asset":{"type":"passage","lines":["가 공연은 몇 시에 시작하나요?  나 2시 30분에 시작합니다.","다 여기 상추 씨앗이 있어.  라 씨앗이 참 작구나!","마 주인공이 병에 걸려서 너무 슬펐어!","바 그 뒤에 주인공은 어떻게 되었을까?","사 종이 가장자리를 모두 안으로 접으면 강아지 모양이 된단다.","아 우아, 신기해요!  자 나랑 공놀이할래?"],"title":"『국어』 108쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
