INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#12','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C5',2,'ox','auto','글쓴이의 마음은 문장의 앞뒤 내용과 함께 짐작해요.',ARRAY['K2-2-u4-X07']::text[],false,'{"seq":12,"concept":"K2-2-u4-C5","difficulty":2,"kind":"ox","stem":"글쓴이의 마음은 문장의 앞뒤 내용과 함께 짐작해요.","answer":"O","reason_options":[{"t":"한 문장만 보면 마음을 잘못 짐작할 수 있으니까","correct":true},{"t":"한 문장만 보면 충분하니까","mis":"K2-2-u4-X07"}],"mis":"K2-2-u4-X07","explanation":["앞뒤를 함께요.","지도서 169쪽이에요.","글 전체에서요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#13','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C5',2,'mc','auto','「그런데 고맙다는 말을 제대로 하지 못해서 이렇게 편지를 써.」에 담긴 마음은?',ARRAY['K2-2-u4-X09','K2-2-u4-X07']::text[],false,'{"seq":13,"concept":"K2-2-u4-C5","difficulty":2,"kind":"mc","stem":"「그런데 고맙다는 말을 제대로 하지 못해서 이렇게 편지를 써.」에 담긴 마음은?","options":[{"t":"고마운 마음을 꼭 전하고 싶은 마음","correct":true},{"t":"편지 쓰기가 귀찮은 마음","mis":"K2-2-u4-X09"},{"t":"달리기에서 이긴 기쁜 마음","mis":"K2-2-u4-X07"}],"explanation":["꼭 전하고 싶어요.","지도서 181쪽이에요.","편지를 쓴 까닭이에요."],"asset":{"type":"passage","lines":["지후에게","지후야, 안녕? 나 민우야.","지후야, 어제 네가 내 가방을 들어 주어서 큰 도움이 되었어.","내가 손을 다쳐서 가방을 어떻게 들까 걱정했거든.","그때 네가 도와준다고 해서 정말 기뻤어!","그런데 고맙다는 말을 제대로 하지 못해서 이렇게 편지를 써."],"title":"『국어』 110쪽 민우가 쓴 편지(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
