INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#16','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C8',2,'mc','auto','『국어활동』 57쪽 — 「얘들아, 어흥! 그 떡 맛있겠다.」 하는 호랑이에게 어울리는 목소리는?',ARRAY['K2-2-u4-X11']::text[],false,'{"seq":16,"concept":"K2-2-u4-C8","difficulty":2,"kind":"mc","stem":"『국어활동』 57쪽 — 「얘들아, 어흥! 그 떡 맛있겠다.」 하는 호랑이에게 어울리는 목소리는?","options":[{"t":"조금 무서운 목소리로 겁주듯이","correct":true},{"t":"느릿느릿 졸린 목소리로","mis":"K2-2-u4-X11"},{"t":"작게 속삭이듯이","mis":"K2-2-u4-X11"}],"explanation":["겁주듯이요.","국어활동 57쪽 예시 답안이에요.","호랑이의 마음이에요."],"asset":{"type":"scene","icon":"🐯🐸🐰🍡","text":"『국어활동』 「떡 먹기 내기」 — 호랑이가 떡을 같이 먹자고 하자 두꺼비와 토끼는 입을 삐죽이며 고개를 끄덕였어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
