INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#18','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C3',3,'mc','auto','「지난 체육 시간에 달리기 경주를 했던 거 기억해?」를 쓴 까닭은?',ARRAY['K2-2-u4-X05']::text[],false,'{"seq":18,"concept":"K2-2-u4-C3","difficulty":3,"kind":"mc","stem":"「지난 체육 시간에 달리기 경주를 했던 거 기억해?」를 쓴 까닭은?","options":[{"t":"달리기 경주를 했던 일을 기억하는지 물으려고","correct":true},{"t":"달리기 방법을 설명하려고","mis":"K2-2-u4-X05"},{"t":"이긴 기쁨을 나타내려고","mis":"K2-2-u4-X05"}],"explanation":["기억하는지 물어요.","112쪽이에요.","묻는 문장이에요."],"asset":{"type":"passage","lines":["지난 체육 시간에 달리기 경주를 했던 거 기억해? 네가 이겼잖아.","달리기만큼은 자신 있었는데 내가 지니까 많이 속상했어.","그래서 그동안 너한테 말도 제대로 하지 않았어.","그런데 너는 오히려 나를 걱정해 주고 가방도 들어 주어서 미안했어.","지후야, 나를 도와주어서 고마워!","앞으로도 친하게 지내자. 그럼 안녕. — 너의 친구 민우 보냄"],"title":"『국어』 110쪽 민우가 쓴 편지(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#19','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C7',3,'mc','auto','「송아지와 바꾼 무」의 흐름으로 알맞은 것은?',ARRAY['K2-2-u4-X10']::text[],false,'{"seq":19,"concept":"K2-2-u4-C7","difficulty":3,"kind":"mc","stem":"「송아지와 바꾼 무」의 흐름으로 알맞은 것은?","options":[{"t":"농부가 무를 바침 → 송아지를 받음 → 욕심꾸러기 농부가 송아지를 바침 → 무를 받음","correct":true},{"t":"욕심꾸러기 농부가 송아지를 바침 → 농부가 무를 바침 → 무를 받음 → 송아지를 받음","mis":"K2-2-u4-X10"},{"t":"농부가 송아지를 받음 → 무를 바침 → 무를 받음 → 송아지를 바침","mis":"K2-2-u4-X10"}],"explanation":["차례대로예요.","120쪽이에요.","그림을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#20','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C2',3,'mc','auto','생일 초대장에 쓸 설명하는 문장으로 알맞은 것은?',ARRAY['K2-2-u4-X03','K2-2-u4-X04']::text[],false,'{"seq":20,"concept":"K2-2-u4-C2","difficulty":3,"kind":"mc","stem":"생일 초대장에 쓸 설명하는 문장으로 알맞은 것은?","options":[{"t":"생일잔치는 토요일 두 시에 우리 집에서 해.","correct":true},{"t":"와 줄 수 있니?","mis":"K2-2-u4-X03"},{"t":"정말 기대된다!","mis":"K2-2-u4-X04"}],"explanation":["설명하는 문장이에요.","지도서 199쪽이에요.","시간과 장소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#21','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C9',3,'mc','auto','「떡 먹기 내기」의 호랑이에게 쓴 편지 내용으로 알맞은 것은?',ARRAY['K2-2-u4-X12']::text[],false,'{"seq":21,"concept":"K2-2-u4-C9","difficulty":3,"kind":"mc","stem":"「떡 먹기 내기」의 호랑이에게 쓴 편지 내용으로 알맞은 것은?","options":[{"t":"다음에는 힘과 덩치만 믿고 욕심내지 않으면 좋겠어.","correct":true},{"t":"호랑이는 정말 못생겼어.","mis":"K2-2-u4-X12"},{"t":"떡은 맛이 없어.","mis":"K2-2-u4-X12"}],"explanation":["바라는 점이에요.","지도서 195쪽 예시예요.","부드럽게요."],"asset":{"type":"scene","icon":"🐯🐸🐰🍡","text":"『국어활동』 「떡 먹기 내기」 — 호랑이가 떡을 같이 먹자고 하자 두꺼비와 토끼는 입을 삐죽이며 고개를 끄덕였어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#22','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C10',3,'mc','auto','목소리 연극에서 대사를 바꾸어도 되는 경우는?',ARRAY['K2-2-u4-X12']::text[],false,'{"seq":22,"concept":"K2-2-u4-C10","difficulty":3,"kind":"mc","stem":"목소리 연극에서 대사를 바꾸어도 되는 경우는?","options":[{"t":"인물의 마음에 어긋나지 않을 때","correct":true},{"t":"아무 말이나 하고 싶을 때","mis":"K2-2-u4-X12"},{"t":"친구를 놀리고 싶을 때","mis":"K2-2-u4-X12"}],"explanation":["마음에 맞게요.","지도서 193쪽이에요.","융통성 있게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#23','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C1',4,'sa','auto','「!」의 이름을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u4-C1","difficulty":4,"kind":"sa","stem":"「!」의 이름을 쓰세요.","answer":["느낌표"],"explanation":["느낌표예요.","105쪽이에요.","감탄할 때요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#24','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C3',4,'essay','teacher','「비가 온다.」를 묻는 문장과 감탄하는 문장으로 바꾸어 쓰고, 각각 언제 쓰면 좋을지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u4-C3","difficulty":4,"kind":"essay","stem":"「비가 온다.」를 묻는 문장과 감탄하는 문장으로 바꾸어 쓰고, 각각 언제 쓰면 좋을지 쓰세요.","answer_guide":{"answer":"예: 비가 오니? — 밖에 비가 오는지 궁금할 때 / 비가 정말 많이 오는구나! — 비가 많이 와서 놀랐을 때","scoring_points":["묻는 문장이에요","감탄하는 문장이에요","쓸 때를 썼어요"]},"explanation":["종류를 바꿔요.","지도서 177쪽이에요.","쓰는 때도 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_b#25','kor',2,2,'u4','','g2_2_kor_u4_review_b','unit_review','K2-2-u4-C6',4,'essay','teacher','「냄새 맡은 값」 뒤에 이어질 이야기를 쓰세요. 구두쇠 영감이 달라졌을지, 똑같이 행동할지 생각해서 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u4-C6","difficulty":4,"kind":"essay","stem":"「냄새 맡은 값」 뒤에 이어질 이야기를 쓰세요. 구두쇠 영감이 달라졌을지, 똑같이 행동할지 생각해서 쓰세요.","answer_guide":{"answer":"예: 다음 날, 구두쇠 영감은 국밥집 앞에 「냄새는 공짜입니다」라고 써 붙였어요. 사람들이 웃으며 국밥을 사 먹으러 왔어요.","scoring_points":["구두쇠 영감의 마음이 드러나요","앞 이야기와 이어져요"]},"explanation":["인물의 마음을 생각해요.","지도서 200쪽이에요.","이어서 써요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#1','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C1',1,'mc','auto','강한 느낌을 나타내는 문장 끝에 쓰는 문장 부호는?',ARRAY['K2-2-u4-X02']::text[],false,'{"seq":1,"concept":"K2-2-u4-C1","difficulty":1,"kind":"mc","stem":"강한 느낌을 나타내는 문장 끝에 쓰는 문장 부호는?","options":[{"t":"!","correct":true},{"t":"?","mis":"K2-2-u4-X02"},{"t":".","mis":"K2-2-u4-X02"}],"explanation":["느낌표예요.","127쪽이에요.","감탄할 때요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#2','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C2',1,'mc','auto','「앗, 차가워!」는 어떤 문장인가요?',ARRAY['K2-2-u4-X03','K2-2-u4-X04']::text[],false,'{"seq":2,"concept":"K2-2-u4-C2","difficulty":1,"kind":"mc","stem":"「앗, 차가워!」는 어떤 문장인가요?","options":[{"t":"감탄하는 문장","correct":true},{"t":"묻는 문장","mis":"K2-2-u4-X03"},{"t":"설명하는 문장","mis":"K2-2-u4-X04"}],"explanation":["감탄하는 문장이에요.","국어활동 49쪽이에요.","놀람도 감정이에요."],"asset":{"type":"passage","lines":["내일 우리 집에 올 수 있어? · 화장실은 복도 끝에 있습니다.","앗, 차가워! · 실내화는 어디에 있나요? · 줄넘기 줄 가져왔어?","시원하고 참 달콤하다! · 수영 수업은 두 시에 시작합니다.","오늘 점심에는 비빔밥을 먹을 거야."],"title":"『국어활동』 48~49쪽 1번 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#3','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C4',1,'mc','auto','웃어른께 편지를 쓸 때 쓴 사람에 쓰는 말은?',ARRAY['K2-2-u4-X06']::text[],false,'{"seq":3,"concept":"K2-2-u4-C4","difficulty":1,"kind":"mc","stem":"웃어른께 편지를 쓸 때 쓴 사람에 쓰는 말은?","options":[{"t":"○○ 올림","correct":true},{"t":"○○ 보냄","mis":"K2-2-u4-X06"},{"t":"○○가","mis":"K2-2-u4-X06"}],"explanation":["올림이에요.","111쪽 도움말이에요.","받는 사람은 「께」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#4','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C5',1,'mc','auto','민우가 편지 끝에서 바란 것은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":4,"concept":"K2-2-u4-C5","difficulty":1,"kind":"mc","stem":"민우가 편지 끝에서 바란 것은?","options":[{"t":"앞으로도 친하게 지내자","correct":true},{"t":"다시 달리기하자","mis":"K2-2-u4-X08"},{"t":"가방을 들어 달라","mis":"K2-2-u4-X08"}],"explanation":["친하게 지내자예요.","110쪽이에요.","바라는 마음이에요."],"asset":{"type":"passage","lines":["지난 체육 시간에 달리기 경주를 했던 거 기억해? 네가 이겼잖아.","달리기만큼은 자신 있었는데 내가 지니까 많이 속상했어.","그래서 그동안 너한테 말도 제대로 하지 않았어.","그런데 너는 오히려 나를 걱정해 주고 가방도 들어 주어서 미안했어.","지후야, 나를 도와주어서 고마워!","앞으로도 친하게 지내자. 그럼 안녕. — 너의 친구 민우 보냄"],"title":"『국어』 110쪽 민우가 쓴 편지(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#5','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C7',1,'mc','auto','최 서방은 국밥집 앞에서 무엇을 했나요?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":5,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"최 서방은 국밥집 앞에서 무엇을 했나요?","options":[{"t":"국밥 냄새를 맡았어요","correct":true},{"t":"국밥을 먹었어요","mis":"K2-2-u4-X08"},{"t":"국밥을 팔았어요","mis":"K2-2-u4-X08"}],"explanation":["냄새를 맡았어요.","114쪽이에요.","그래서 값 이야기가 나왔어요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#6','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C7',1,'mc','auto','사또에게 송아지를 가져다준 사람은?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":6,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"사또에게 송아지를 가져다준 사람은?","options":[{"t":"이방","correct":true},{"t":"욕심꾸러기 농부의 아들","mis":"K2-2-u4-X08"},{"t":"최 서방","mis":"K2-2-u4-X08"}],"explanation":["이방이에요.","지도서 191쪽이에요.","사또가 불렀어요."],"asset":{"type":"passage","lines":["농부가 밭에서 커다란 무를 간신히 뽑았습니다.","「세상에나! 이렇게 커다랗다니!」 농부는 신이 나서 어깨를 들썩거렸습니다.","「사또께 이 무를 바치고 싶습니다.」","사또는 껄껄껄 웃으며 보답으로 송아지 한 마리를 주었습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
