INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#8','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C10',1,'mc','auto','목소리 연극을 할 때 역할은 어떻게 나누나요?',ARRAY['K2-2-u4-X15']::text[],false,'{"seq":8,"concept":"K2-2-u4-C10","difficulty":1,"kind":"mc","stem":"목소리 연극을 할 때 역할은 어떻게 나누나요?","options":[{"t":"하고 싶은 역할을 사이좋게 나누어요","correct":true},{"t":"한 사람이 다 해요","mis":"K2-2-u4-X15"},{"t":"선생님만 해요","mis":"K2-2-u4-X15"}],"explanation":["사이좋게요.","지도서 193쪽이에요.","바꾸어 연습해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#9','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C3',2,'mc','auto','「주인공이 병에 걸려서 너무 슬펐어!」를 쓴 까닭은?',ARRAY['K2-2-u4-X05']::text[],false,'{"seq":9,"concept":"K2-2-u4-C3","difficulty":2,"kind":"mc","stem":"「주인공이 병에 걸려서 너무 슬펐어!」를 쓴 까닭은?","options":[{"t":"영화를 본 느낌을 표현하려고","correct":true},{"t":"영화 시간을 물으려고","mis":"K2-2-u4-X05"},{"t":"주인공 이름을 설명하려고","mis":"K2-2-u4-X05"}],"explanation":["느낌을 표현해요.","109쪽이에요.","감탄하는 문장이에요."],"asset":{"type":"passage","lines":["가 공연은 몇 시에 시작하나요?  나 2시 30분에 시작합니다.","다 여기 상추 씨앗이 있어.  라 씨앗이 참 작구나!","마 주인공이 병에 걸려서 너무 슬펐어!","바 그 뒤에 주인공은 어떻게 되었을까?","사 종이 가장자리를 모두 안으로 접으면 강아지 모양이 된단다.","아 우아, 신기해요!  자 나랑 공놀이할래?"],"title":"『국어』 108쪽 4번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#10','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C6',2,'mc','auto','신이 나서 어깨를 들썩거린 농부의 마음은?',ARRAY['K2-2-u4-X09']::text[],false,'{"seq":10,"concept":"K2-2-u4-C6","difficulty":2,"kind":"mc","stem":"신이 나서 어깨를 들썩거린 농부의 마음은?","options":[{"t":"즐겁고 뿌듯해요","correct":true},{"t":"화나요","mis":"K2-2-u4-X09"},{"t":"후회스러워요","mis":"K2-2-u4-X09"}],"explanation":["즐겁고 뿌듯해요.","121쪽 예시 답안이에요.","행동이 근거예요."],"asset":{"type":"passage","lines":["농부가 밭에서 커다란 무를 간신히 뽑았습니다.","「세상에나! 이렇게 커다랗다니!」 농부는 신이 나서 어깨를 들썩거렸습니다.","「사또께 이 무를 바치고 싶습니다.」","사또는 껄껄껄 웃으며 보답으로 송아지 한 마리를 주었습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#11','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C6',2,'match','auto','인물의 말이나 행동과 마음을 이어 보세요.','{}'::text[],false,'{"seq":11,"concept":"K2-2-u4-C6","difficulty":2,"kind":"match","stem":"인물의 말이나 행동과 마음을 이어 보세요.","pairs":[{"l":"구두쇠 영감: 「냄새 맡은 값을 치르고 가야지.」","r":"괘씸하다"},{"l":"최 서방: 「냄새 맡은 값이라니요?」","r":"어이없다"},{"l":"욕심꾸러기 농부: 「아이고, 아까운 내 송아지!」","r":"후회스럽다"}],"mis":"K2-2-u4-X09","explanation":["말이 근거예요.","118·121쪽이에요.","마음을 짐작해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#12','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C8',2,'ox','auto','실감 나게 읽기는 성우처럼 목소리를 흉내 내는 것이 목적이에요.',ARRAY['K2-2-u4-X11']::text[],false,'{"seq":12,"concept":"K2-2-u4-C8","difficulty":2,"kind":"ox","stem":"실감 나게 읽기는 성우처럼 목소리를 흉내 내는 것이 목적이에요.","answer":"X","reason_options":[{"t":"인물의 마음을 짐작해 이야기 내용을 잘 표현하는 것이 목적이니까","correct":true},{"t":"목소리 흉내가 가장 중요하니까","mis":"K2-2-u4-X11"}],"mis":"K2-2-u4-X11","explanation":["흉내가 아니에요.","지도서 182쪽이에요.","마음을 표현해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#13','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C5',2,'mc','auto','「지후야, 나를 도와주어서 고마워!」에 담긴 마음은?',ARRAY['K2-2-u4-X07','K2-2-u4-X09']::text[],false,'{"seq":13,"concept":"K2-2-u4-C5","difficulty":2,"kind":"mc","stem":"「지후야, 나를 도와주어서 고마워!」에 담긴 마음은?","options":[{"t":"도와줄 줄 몰랐는데 도와주어서 고마운 마음","correct":true},{"t":"도와줄 줄 알아서 당연한 마음","mis":"K2-2-u4-X07"},{"t":"도움이 필요 없었다는 마음","mis":"K2-2-u4-X09"}],"explanation":["고마운 마음이에요.","지도서 181쪽이에요.","앞의 속상함과 이어져요."],"asset":{"type":"passage","lines":["지난 체육 시간에 달리기 경주를 했던 거 기억해? 네가 이겼잖아.","달리기만큼은 자신 있었는데 내가 지니까 많이 속상했어.","그래서 그동안 너한테 말도 제대로 하지 않았어.","그런데 너는 오히려 나를 걱정해 주고 가방도 들어 주어서 미안했어.","지후야, 나를 도와주어서 고마워!","앞으로도 친하게 지내자. 그럼 안녕. — 너의 친구 민우 보냄"],"title":"『국어』 110쪽 민우가 쓴 편지(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
