INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#19','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C6',3,'mc','auto','사또가 욕심꾸러기 농부에게 커다란 무를 준 까닭은?',ARRAY['K2-2-u4-X08','K2-2-u4-X09']::text[],false,'{"seq":19,"concept":"K2-2-u4-C6","difficulty":3,"kind":"mc","stem":"사또가 욕심꾸러기 농부에게 커다란 무를 준 까닭은?","options":[{"t":"욕심으로 선물한 마음을 알아보았기 때문이에요","correct":true},{"t":"무가 너무 많아서요","mis":"K2-2-u4-X08"},{"t":"송아지가 싫어서요","mis":"K2-2-u4-X09"}],"explanation":["마음을 알아보았어요.","127쪽이에요.","시원한 결말이에요."],"asset":{"type":"passage","lines":["욕심꾸러기 농부가 「아이고, 배 아파! 무 하나에 송아지 한 마리라니!」","「사또께 송아지를 갖다 바치면 더 큰 선물을 받겠지?」","사또는 며칠 전에 들어온 커다란 무를 욕심꾸러기 농부에게 주었습니다.","「아이고, 아까운 내 송아지!」 욕심꾸러기 농부는 울면서 돌아왔습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#20','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C2',3,'mc','auto','생일 초대장에 쓸 감탄하는 문장으로 알맞은 것은?',ARRAY['K2-2-u4-X04','K2-2-u4-X03']::text[],false,'{"seq":20,"concept":"K2-2-u4-C2","difficulty":3,"kind":"mc","stem":"생일 초대장에 쓸 감탄하는 문장으로 알맞은 것은?","options":[{"t":"친구들과 함께하면 정말 즐거울 거야!","correct":true},{"t":"케이크는 딸기 맛이야.","mis":"K2-2-u4-X04"},{"t":"누구누구 올 수 있어?","mis":"K2-2-u4-X03"}],"explanation":["감탄하는 문장이에요.","지도서 199쪽이에요.","느낌표예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#21','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C9',3,'mc','auto','인물이 되어 의자에 앉은 친구에게 할 질문으로 알맞은 것은?',ARRAY['K2-2-u4-X12']::text[],false,'{"seq":21,"concept":"K2-2-u4-C9","difficulty":3,"kind":"mc","stem":"인물이 되어 의자에 앉은 친구에게 할 질문으로 알맞은 것은?","options":[{"t":"농부님, 커다란 무가 나왔을 때 어떤 마음이 드셨나요?","correct":true},{"t":"농부님, 오늘 점심은 뭐 드셨어요?","mis":"K2-2-u4-X12"},{"t":"농부님은 왜 바보예요?","mis":"K2-2-u4-X12"}],"explanation":["마음을 묻는 질문이에요.","123쪽이에요.","이야기와 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#22','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C10',3,'mc','auto','목소리 연극을 하는 사람(실연자)이 스스로 확인할 것은?',ARRAY['K2-2-u4-X11']::text[],false,'{"seq":22,"concept":"K2-2-u4-C10","difficulty":3,"kind":"mc","stem":"목소리 연극을 하는 사람(실연자)이 스스로 확인할 것은?","options":[{"t":"인물의 마음을 잘 이해하고 실감 나게 표현했나요?","correct":true},{"t":"관객보다 크게 웃었나요?","mis":"K2-2-u4-X11"},{"t":"대사를 하나도 안 바꿨나요?","mis":"K2-2-u4-X11"}],"explanation":["마음을 표현했는지요.","지도서 193쪽이에요.","자기 평가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#23','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C4',4,'sa','auto','웃어른께 쓰는 편지에서 쓴 사람 이름 뒤에 쓰는 두 글자를 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u4-C4","difficulty":4,"kind":"sa","stem":"웃어른께 쓰는 편지에서 쓴 사람 이름 뒤에 쓰는 두 글자를 쓰세요.","answer":["올림"],"explanation":["올림이에요.","111쪽이에요.","받는 사람은 「께」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#24','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C5',4,'essay','teacher','민우의 편지를 읽고 지후가 되어 민우에게 짧은 답장을 쓰세요. 감탄하는 문장을 하나 넣으세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u4-C5","difficulty":4,"kind":"essay","stem":"민우의 편지를 읽고 지후가 되어 민우에게 짧은 답장을 쓰세요. 감탄하는 문장을 하나 넣으세요.","answer_guide":{"answer":"예: 민우에게 / 민우야, 편지 고마워. 네가 다쳐서 걱정했어. 이제 다 나아서 정말 다행이야! 앞으로도 친하게 지내자. / 너의 친구 지후가","scoring_points":["민우의 편지와 이어져요","감탄하는 문장이 있어요","편지 짜임이 있어요"]},"explanation":["지후의 마음을 생각해요.","편지로 답해요.","110쪽이에요."],"asset":{"type":"passage","lines":["지난 체육 시간에 달리기 경주를 했던 거 기억해? 네가 이겼잖아.","달리기만큼은 자신 있었는데 내가 지니까 많이 속상했어.","그래서 그동안 너한테 말도 제대로 하지 않았어.","그런데 너는 오히려 나를 걱정해 주고 가방도 들어 주어서 미안했어.","지후야, 나를 도와주어서 고마워!","앞으로도 친하게 지내자. 그럼 안녕. — 너의 친구 민우 보냄"],"title":"『국어』 110쪽 민우가 쓴 편지(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_c#25','kor',2,2,'u4','','g2_2_kor_u4_review_c','unit_review','K2-2-u4-C6',4,'essay','teacher','「송아지와 바꾼 무」 뒤에 이어질 이야기를 쓰세요. 욕심꾸러기 농부가 어떻게 달라졌을지 상상해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u4-C6","difficulty":4,"kind":"essay","stem":"「송아지와 바꾼 무」 뒤에 이어질 이야기를 쓰세요. 욕심꾸러기 농부가 어떻게 달라졌을지 상상해 쓰세요.","answer_guide":{"answer":"예: 욕심꾸러기 농부는 커다란 무로 국을 끓여 이웃과 나누어 먹었어요. 「욕심 대신 나누니 마음이 편하구나.」","scoring_points":["욕심꾸러기 농부의 마음이 드러나요","앞 이야기와 이어져요"]},"explanation":["마음이 바뀌었을지 생각해요.","지도서 200쪽이에요.","이어서 써요."],"asset":{"type":"passage","lines":["욕심꾸러기 농부가 「아이고, 배 아파! 무 하나에 송아지 한 마리라니!」","「사또께 송아지를 갖다 바치면 더 큰 선물을 받겠지?」","사또는 며칠 전에 들어온 커다란 무를 욕심꾸러기 농부에게 주었습니다.","「아이고, 아까운 내 송아지!」 욕심꾸러기 농부는 울면서 돌아왔습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
