INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#2','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C2',1,'mc','auto','「줄넘기 줄 가져왔어?」는 어떤 문장인가요?',ARRAY['K2-2-u4-X03','K2-2-u4-X02']::text[],false,'{"seq":2,"concept":"K2-2-u4-C2","difficulty":1,"kind":"mc","stem":"「줄넘기 줄 가져왔어?」는 어떤 문장인가요?","options":[{"t":"묻는 문장","correct":true},{"t":"설명하는 문장","mis":"K2-2-u4-X03"},{"t":"감탄하는 문장","mis":"K2-2-u4-X02"}],"explanation":["묻는 문장이에요.","국어활동 49쪽이에요.","물음표예요."],"asset":{"type":"passage","lines":["내일 우리 집에 올 수 있어? · 화장실은 복도 끝에 있습니다.","앗, 차가워! · 실내화는 어디에 있나요? · 줄넘기 줄 가져왔어?","시원하고 참 달콤하다! · 수영 수업은 두 시에 시작합니다.","오늘 점심에는 비빔밥을 먹을 거야."],"title":"『국어활동』 48~49쪽 1번 문장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
