INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#4','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C5',1,'mc','auto','민우의 편지를 받은 지후의 마음으로 알맞은 것은?',ARRAY['K2-2-u4-X09']::text[],false,'{"seq":4,"concept":"K2-2-u4-C5","difficulty":1,"kind":"mc","stem":"민우의 편지를 받은 지후의 마음으로 알맞은 것은?","options":[{"t":"쑥스럽고 기뻤을 것 같아요","correct":true},{"t":"화가 났을 것 같아요","mis":"K2-2-u4-X09"},{"t":"지루했을 것 같아요","mis":"K2-2-u4-X09"}],"explanation":["쑥스럽고 기뻐요.","127쪽 예시 답안이에요.","고맙다는 편지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#5','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C7',1,'mc','auto','이야기 끝에서 구두쇠 영감은 어떻게 되었나요?',ARRAY['K2-2-u4-X08']::text[],false,'{"seq":5,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"이야기 끝에서 구두쇠 영감은 어떻게 되었나요?","options":[{"t":"아무 말도 못 하고 얼굴이 빨개졌어요","correct":true},{"t":"최 서방에게 엽전을 받았어요","mis":"K2-2-u4-X08"},{"t":"크게 웃었어요","mis":"K2-2-u4-X08"}],"explanation":["얼굴이 빨개졌어요.","116쪽이에요.","사람들이 웃었어요."],"asset":{"type":"passage","lines":["구두쇠 영감의 국밥집은 장사가 아주 잘되었어요.","최 서방이 지나가다 국밥 냄새를 맡고 감탄했어요.","영감이 눈을 부릅뜨고 붙잡아 냄새 맡은 값을 내라고 했어요.","최 서방은 돈주머니를 영감의 귀에 대고 흔들었어요.","「자, 이 소리가 들리지요?」 — 엽전 소리로 값을 치른 거예요.","영감은 아무 말도 못 하고 얼굴이 빨개졌어요."],"title":"『국어』 114~116쪽 「냄새 맡은 값」 간추림"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#6','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C7',1,'mc','auto','농부가 커다란 무를 사또께 바친 까닭은?',ARRAY['K2-2-u4-X08','K2-2-u4-X09']::text[],false,'{"seq":6,"concept":"K2-2-u4-C7","difficulty":1,"kind":"mc","stem":"농부가 커다란 무를 사또께 바친 까닭은?","options":[{"t":"귀한 무를 그냥 먹을 수 없어서","correct":true},{"t":"무가 맛이 없어서","mis":"K2-2-u4-X08"},{"t":"송아지를 받고 싶어서","mis":"K2-2-u4-X09"}],"explanation":["귀해서요.","지도서 191쪽이에요.","욕심이 아니었어요."],"asset":{"type":"passage","lines":["농부가 밭에서 커다란 무를 간신히 뽑았습니다.","「세상에나! 이렇게 커다랗다니!」 농부는 신이 나서 어깨를 들썩거렸습니다.","「사또께 이 무를 바치고 싶습니다.」","사또는 껄껄껄 웃으며 보답으로 송아지 한 마리를 주었습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(앞부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
