INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#9','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C3',2,'mc','auto','「이가 너무 아파요!」를 쓴 까닭은?',ARRAY['K2-2-u4-X05']::text[],false,'{"seq":9,"concept":"K2-2-u4-C3","difficulty":2,"kind":"mc","stem":"「이가 너무 아파요!」를 쓴 까닭은?","options":[{"t":"이가 아픈 느낌을 강하게 나타내려고","correct":true},{"t":"치과가 어디 있는지 물으려고","mis":"K2-2-u4-X05"},{"t":"이를 닦는 방법을 설명하려고","mis":"K2-2-u4-X05"}],"explanation":["아픈 느낌이에요.","107쪽이에요.","감탄하는 문장이에요."],"asset":{"type":"passage","lines":["가 「난 줄넘기를 좋아해.」 「그래? 나는 축구가 가장 재미있어.」","나 「우체국이 어디 있나요?」","   「저기 모퉁이를 돌면 우체국이 바로 보이실 거예요.」","다 「이가 너무 아파요!」 「그래, 많이 아팠겠구나. 금방 치료해 줄게.」"],"title":"『국어』 106쪽 1번"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
