INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#12','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C9',2,'ox','auto','인물에게 하고 싶은 말을 할 때 인물을 놀리는 말을 해도 돼요.',ARRAY['K2-2-u4-X12']::text[],false,'{"seq":12,"concept":"K2-2-u4-C9","difficulty":2,"kind":"ox","stem":"인물에게 하고 싶은 말을 할 때 인물을 놀리는 말을 해도 돼요.","answer":"X","reason_options":[{"t":"인물의 마음을 헤아리며 생각을 전해야 하니까","correct":true},{"t":"이야기 속 인물이니 괜찮으니까","mis":"K2-2-u4-X12"}],"mis":"K2-2-u4-X12","explanation":["놀리지 않아요.","122쪽이에요.","헤아리며 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#13','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C5',2,'mc','auto','민우의 편지를 다시 읽고 짐작한 글쓴이의 마음으로 알맞은 것은?',ARRAY['K2-2-u4-X07','K2-2-u4-X09']::text[],false,'{"seq":13,"concept":"K2-2-u4-C5","difficulty":2,"kind":"mc","stem":"민우의 편지를 다시 읽고 짐작한 글쓴이의 마음으로 알맞은 것은?","options":[{"t":"속상했지만 도와준 지후에게 미안하고 고마운 마음","correct":true},{"t":"지후를 계속 미워하는 마음","mis":"K2-2-u4-X07"},{"t":"가방이 무거워 짜증 난 마음","mis":"K2-2-u4-X09"}],"explanation":["여러 마음이 있어요.","113쪽 (3)이에요.","글 전체에서요."],"asset":{"type":"passage","lines":["지난 체육 시간에 달리기 경주를 했던 거 기억해? 네가 이겼잖아.","달리기만큼은 자신 있었는데 내가 지니까 많이 속상했어.","그래서 그동안 너한테 말도 제대로 하지 않았어.","그런데 너는 오히려 나를 걱정해 주고 가방도 들어 주어서 미안했어.","지후야, 나를 도와주어서 고마워!","앞으로도 친하게 지내자. 그럼 안녕. — 너의 친구 민우 보냄"],"title":"『국어』 110쪽 민우가 쓴 편지(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
