INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#18','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C3',3,'mc','auto','「여러분, 안녕하세요?」에 물음표를 쓴 까닭은?',ARRAY['K2-2-u4-X02','K2-2-u4-X05']::text[],false,'{"seq":18,"concept":"K2-2-u4-C3","difficulty":3,"kind":"mc","stem":"「여러분, 안녕하세요?」에 물음표를 쓴 까닭은?","options":[{"t":"안부를 묻는 인사라서","correct":true},{"t":"기쁜 느낌이 강해서","mis":"K2-2-u4-X02"},{"t":"그림을 설명해서","mis":"K2-2-u4-X05"}],"explanation":["안부를 물어요.","102쪽이에요.","뜻에 맞는 부호예요."],"asset":{"type":"passage","lines":["초등학교 2학년 어린이들에게","여러분, 안녕하세요? 저는 미술관 관장입니다.","지난 화요일에 우리 미술관을 방문해 주어서 고마웠어요.","즐거운 시간 보냈나요? 저도 여러분을 만나 매우 반가웠어요!","어떤 작품이 가장 기억에 남았나요?","정말 멋진 작품들이에요!","여러분을 특별 전시회에 초대하고 싶어요. 꼭 와 주길 바라요.","미술관 관장 씀"],"title":"『국어』 102~103쪽 미술관 관장님의 편지(일부)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#19','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C6',3,'mc','auto','『국어활동』 「떡 먹기 내기」 — 떡을 혼자 다 먹을 생각에 저절로 웃음이 난 인물의 마음은?',ARRAY['K2-2-u4-X09']::text[],false,'{"seq":19,"concept":"K2-2-u4-C6","difficulty":3,"kind":"mc","stem":"『국어활동』 「떡 먹기 내기」 — 떡을 혼자 다 먹을 생각에 저절로 웃음이 난 인물의 마음은?","options":[{"t":"신나고 기대돼요","correct":true},{"t":"불만스럽고 억울해요","mis":"K2-2-u4-X09"},{"t":"무서워요","mis":"K2-2-u4-X09"}],"explanation":["신나고 기대돼요.","국어활동 56쪽 예시 답안이에요.","웃음이 근거예요."],"asset":{"type":"scene","icon":"🐯🐸🐰🍡","text":"『국어활동』 「떡 먹기 내기」 — 호랑이가 떡을 같이 먹자고 하자 두꺼비와 토끼는 입을 삐죽이며 고개를 끄덕였어요."}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#20','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C10',3,'mc','auto','지도서 199쪽 — 초대장을 발표할 때 스스로 확인할 것으로 알맞은 것은?',ARRAY['K2-2-u4-X15']::text[],false,'{"seq":20,"concept":"K2-2-u4-C10","difficulty":3,"kind":"mc","stem":"지도서 199쪽 — 초대장을 발표할 때 스스로 확인할 것으로 알맞은 것은?","options":[{"t":"듣는 사람을 바라보며 알맞은 목소리로 발표했나요?","correct":true},{"t":"가장 빨리 발표했나요?","mis":"K2-2-u4-X15"},{"t":"친구 발표를 듣지 않았나요?","mis":"K2-2-u4-X15"}],"explanation":["바른 자세예요.","지도서 199쪽이에요.","자기 평가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#21','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C9',3,'mc','auto','인물에게 전하고 싶은 말로 알맞지 않은 것은?',ARRAY['K2-2-u4-X12']::text[],false,'{"seq":21,"concept":"K2-2-u4-C9","difficulty":3,"kind":"mc","stem":"인물에게 전하고 싶은 말로 알맞지 않은 것은?","options":[{"t":"이야기와 상관없이 내 자랑을 늘어놓는 말","correct":true},{"t":"인물의 행동을 칭찬하는 말","mis":"K2-2-u4-X12"},{"t":"인물에게 궁금한 점을 묻는 말","mis":"K2-2-u4-X12"}],"explanation":["이야기와 이어져야 해요.","122쪽이에요.","인물을 헤아려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#22','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C10',3,'mc','auto','목소리 연극을 보는 사람(관찰자)이 살펴볼 것은?',ARRAY['K2-2-u4-X15','K2-2-u4-X11']::text[],false,'{"seq":22,"concept":"K2-2-u4-C10","difficulty":3,"kind":"mc","stem":"목소리 연극을 보는 사람(관찰자)이 살펴볼 것은?","options":[{"t":"인물의 마음을 어울리는 목소리로 표현하는가","correct":true},{"t":"누가 옷을 예쁘게 입었는가","mis":"K2-2-u4-X15"},{"t":"누가 가장 빨리 말하는가","mis":"K2-2-u4-X11"}],"explanation":["목소리와 마음이에요.","지도서 193쪽이에요.","동료 평가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#23','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C11',4,'sa','auto','「천둥」과 뜻이 비슷한 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"K2-2-u4-C11","difficulty":4,"kind":"sa","stem":"「천둥」과 뜻이 비슷한 낱말을 두 글자로 쓰세요.","answer":["우레"],"explanation":["우레예요.","128쪽이에요.","바꾸어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#24','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C4',4,'essay','teacher','가족 중 웃어른 한 분께 고마운 마음을 전하는 편지를 쓰세요. 「○○께」와 「○○ 올림」을 바르게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K2-2-u4-C4","difficulty":4,"kind":"essay","stem":"가족 중 웃어른 한 분께 고마운 마음을 전하는 편지를 쓰세요. 「○○께」와 「○○ 올림」을 바르게 쓰세요.","answer_guide":{"answer":"예: 할머니께 / 할머니, 안녕하세요? 저 서준이에요. 맛있는 반찬을 해 주셔서 감사해요. 건강하세요. 그럼 안녕히 계세요. / 20○○년 ○○월 ○○일 / 손자 서준 올림","scoring_points":["받는 사람에 「께」를 썼어요","쓴 사람에 「올림」을 썼어요","고마운 마음이 있어요"]},"explanation":["웃어른께는 께·올림이에요.","111쪽 도움말이에요.","마음을 담아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g2_2_kor_u4_review_d#25','kor',2,2,'u4','','g2_2_kor_u4_review_d','unit_review','K2-2-u4-C8',4,'essay','teacher','「송아지와 바꾼 무」에서 한 장면을 골라, 그 장면의 인물의 말을 어떤 목소리로 읽을지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K2-2-u4-C8","difficulty":4,"kind":"essay","stem":"「송아지와 바꾼 무」에서 한 장면을 골라, 그 장면의 인물의 말을 어떤 목소리로 읽을지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「아이고, 아까운 내 송아지!」 — 울먹이며 떨리는 목소리로 읽겠어요. 송아지를 잃어 후회스럽고 속상한 마음이기 때문이에요.","scoring_points":["장면과 말을 골랐어요","목소리를 썼어요","까닭에 인물의 마음이 있어요"]},"explanation":["마음 먼저요.","목소리를 골라요.","119쪽처럼요."],"asset":{"type":"passage","lines":["욕심꾸러기 농부가 「아이고, 배 아파! 무 하나에 송아지 한 마리라니!」","「사또께 송아지를 갖다 바치면 더 큰 선물을 받겠지?」","사또는 며칠 전에 들어온 커다란 무를 욕심꾸러기 농부에게 주었습니다.","「아이고, 아까운 내 송아지!」 욕심꾸러기 농부는 울면서 돌아왔습니다."],"title":"지도서 191쪽 듣기 자료 「송아지와 바꾼 무」(뒷부분)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
